window.NIGHTS=window.NIGHTS||{cases:{}};
window.NIGHTS.cases[6]={"nr":6,"id":"case06","title":"Der Alchemist","subtitle":"","level":"Mystische Ebene","from":151,"to":175,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":151,"layer":null,"blocks":3},{"id":"armand-kais-geschichte","kind":"place","title":"ARMAND KAIS GESCHICHTE","page":152,"layer":null,"blocks":21},{"id":"canseliet-manor","kind":"place","title":"CANSELIET MANOR","page":154,"layer":null,"blocks":8},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":155,"layer":null,"blocks":8},{"id":"canseliet-manor-grund-stueck-und-aussenanlagen","kind":"place","title":"CANSELIET MANOR: GRUND- STÜCK UND AUSSENANLAGEN","page":155,"layer":"schicht-0-aufhaenger","blocks":21},{"id":"schicht-1-das-herrenhaus","kind":"layer","title":"SCHICHT 1: DAS HERRENHAUS","page":159,"layer":null,"blocks":17},{"id":"das-verlassene-haus","kind":"place","title":"DAS VERLASSENE HAUS","page":160,"layer":"schicht-1-das-herrenhaus","blocks":19},{"id":"quartier-der-juenger-innen","kind":"place","title":"QUARTIER DER JÜNGER:INNEN","page":161,"layer":"schicht-1-das-herrenhaus","blocks":27},{"id":"ichor-destillerie","kind":"place","title":"ICHOR-DESTILLERIE","page":163,"layer":"schicht-1-das-herrenhaus","blocks":15},{"id":"schicht-2-die-zisterne","kind":"layer","title":"SCHICHT 2: DIE ZISTERNE","page":164,"layer":null,"blocks":1},{"id":"aqua-fortis-zisterne","kind":"place","title":"AQUA-FORTIS-ZISTERNE","page":164,"layer":"schicht-2-die-zisterne","blocks":41},{"id":"schicht-3-narrengold","kind":"layer","title":"SCHICHT 3: NARRENGOLD","page":167,"layer":null,"blocks":19},{"id":"essenz-gewoelbe","kind":"place","title":"ESSENZ-GEWÖLBE","page":168,"layer":"schicht-3-narrengold","blocks":38},{"id":"schicht-4-armands-labor","kind":"layer","title":"SCHICHT 4: ARMANDS LABOR","page":170,"layer":null,"blocks":1},{"id":"armands-labor","kind":"place","title":"ARMANDS LABOR","page":170,"layer":"schicht-4-armands-labor","blocks":49}],"pages":{"151":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN DIEBSTAHL ALCHEMISTISCHER TRANSMUTATIONEN AUS</b>","sz":20.0,"box":[97.4,776.1,506.3,796.1],"p":151,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"152":{"tab":"","blocks":[{"t":"p","x":"Am Rande der Altstadt steht ein altes, verlassenes Herrenhaus, das niemand betritt. Gerüchten zufolge gehörte es einst einem alternden Alchemisten, der nach dem Geheimnis des ewigen Lebens suchte und sich mit der Alchemie der Seelen beschäftigte. Seine Schüler:innen und Anhänger:innen, Überbleibsel seines dunklen Kults, bewachen das Gebäude bis heute, in der Hoffnung, dem Wissen ihres Meisters auf die Spur zu kommen. Selbst sie wagen sich nicht in die Tiefen, um nicht zu Ingredienzen des letzten Experiments zu werden. Ihr habt diesen Luxus nicht. Nein, ihr müsst das „Große Werk“ des Alchemisten finden, auch wenn ihr dabei zu etwas anderem werdet ...","sz":13.0,"box":[53.9,60.1,286.3,319.6],"p":152,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Der Alchemist</i> ist ein Fall, der sich auf einen einzigen Schauplatz konzentriert und den du als Raubzug oder Dungeon Crawl anlegen kannst. Es handelt sich um das Versteck Armand Kais, eines Meisteralchemisten, den die Angst vor dem Tod plagt und der sich am liebsten aus der lärmenden Stadt zurückziehen würde, um sein Werk zu vollenden: ein Mittel zu finden, um ewig zu leben. Die gesamte Struktur seines Anwesens ist wie ein „Chemiebaukasten“ aufgebaut, in dem das Team das Ausgangsmaterial ist, das sich auf dem Weg zur ultimativen Belohnung, dem Elixier des Lebens, verändert.","sz":9.5,"box":[53.9,330.1,282.9,477.1],"p":152,"i":1,"sec":"titel-und-pitch"},{"t":"h","x":"ARMAND KAIS GESCHICHTE","sz":16.0,"box":[53.9,529.1,237.6,545.1],"p":152,"i":2,"skip":true,"sec":"armand-kais-geschichte"},{"t":"p","x":"In den Anfangsjahren der Stadt war Armand Kai (Fulcanelli, ein sagenumwobener Meisteralchemist) ein junger Akademiker mit Hang zu Spiritismus und Mystik. Tagsüber deutete er obskure Texte, nachts besuchte er Séancen, übersinnliche Lesungen und Treffen von Orden, um die Geheimnisse der Seele, des Universums und des menschlichen Daseins zu ergründen. Seine Suche führte ihn zur Alchemie, die nicht nur zur Umwandlung der Materie, sondern auch der Seele dient. Der eifrige Sucher war fasziniert von den Möglichkeiten, die ihm diese uralte Wissenschaft bot, insbesondere davon, das eigene Wesen über die sterblichen Anfänge hinaus zu bewahren und so geistige Erleuchtung und enorme mystische Kräfte zu erlangen. Bald, nach dem Studium alter alchemistische Lehren, hatte er seine erste spirituelle Erfahrung und erwachte als Riss Fulcanellis.","sz":9.5,"box":[53.9,549.1,286.7,758.6],"p":152,"i":3,"sec":"armand-kais-geschichte"},{"t":"h","x":"FULCANELLI: MYTHOS ODER WIRKLICHKEIT?","sz":13.5,"box":[320.3,60.9,523.1,74.4],"p":152,"i":4,"sec":"armand-kais-geschichte"},{"t":"p","x":"Real war Fulcanelli der Name eines mysteriösen französischen Alchemisten, der in den zwanziger Jahren des zwanzigsten Jahrhunderts aktiv war und dessen Werke sich mit Transformation und Esoterik befassten. Es ist unklar, wer er war oder ob es ihn überhaupt gab. Angeblich verschwand er nach dem Zweiten Weltkrieg, und nur sein Schüler Eugène Canseliet blieb übrig, um von unglaublichen Experimenten zu berichten. <i>Der Morgen der Magier</i>, ein Sammelband paranormaler Geschichten, machte seinen Mythos populär.","sz":9.0,"box":[320.3,87.1,529.4,216.1],"p":152,"i":5,"sec":"armand-kais-geschichte"},{"t":"p","x":"Jahre vergingen, und Armands Verständnis der Alchemie und des Okkulten wurde immer umfassender. Sein Studium des Nebels offenbarte ihm zu seinem Erstaunen, wie umfassend der Bann war, der auf der Stadt lastete. Trotz seiner wachsenden Kräfte gab es immer die Barriere, die ihn und alle anderen in der Stadt hinderte, ihr Potenzial voll auszuschöpfen und Zugang zu einer Realität jenseits der weltlichen Existenz zu finden. Tapfer und unnachgiebig begab sich Armand auf die Suche nach dem Heiligen Gral der spirituell Suchenden: dem Grund für alles. Er ahnte nicht, dass sie ihn am Ende buchstäblich zur Gralsburg führen würde.","sz":9.5,"box":[309.0,250.6,540.3,397.6],"p":152,"i":6,"sec":"armand-kais-geschichte"},{"t":"sh","x":"<b>BEGEGNUNG MIT PAYNE</b>","sz":10.0,"box":[309.4,411.2,441.8,421.2],"p":152,"i":7,"sec":"armand-kais-geschichte"},{"t":"p","x":"Als er diese Gralsburg – Corbin Tower – gefunden hatte, war Armand ein Mann mittleren Alters, müde von seiner Suche nach der letzten Wahrheit, aber leidenschaftlich wie eh und je. In dem zerfallenden Wolkenkratzer fand er einen Todesqualen leidenden Corbin Payne vor, der von seiner schwärenden Wunde bereits schwer geschädigt war. Armand erfuhr, dass der alte „König“ sich vom unbewussten Schmerz der Stadt ernährte und ihn aufrechterhielt und dass der Nebel sich diesen Schmerz zunutze machte, um die Bewohner:innen unter Kontrolle zu halten. Wenn er die Alchemie nutzen könnte, um ein Heilmittel für den König zu finden, würde der Schmerz enden, und die Stadt könnte den ersten Schritt in Richtung Freiheit machen.","sz":9.5,"box":[309.0,426.7,539.5,598.7],"p":152,"i":8,"sec":"armand-kais-geschichte"},{"t":"p","x":"Corbin Payne hatte andere Pläne oder konnte nicht anders, als anderen sein eigenes Leiden zuzufügen. Der Fischerkönig spürte die Ängste, die der Alchemist in sich trug, und offenbarte sich ihm als alter, gebrechlicher Mann mit blutender Wunde. Diese erschreckende Vision von Elend und Verfall, bevorstehendem Tod und menschlichem Ende brannten sich in Armands Gedächtnis ein, gab ihm die „Nimmer heilende Wunde“ (s. S. 18). Sie bringt Armands verborgenes Motiv an den Tag: eine krankhafte Angst vor Alter und Tod, ein verzweifeltes Aufbäumen gegen die Gesetze der Zeit, ein Kampf um eine Zukunft, um einen Weg zu finden, sein Leben zu erhalten – koste es, was es wolle.","sz":9.5,"box":[309.0,607.4,541.6,766.9],"p":152,"i":9,"sec":"armand-kais-geschichte"}],"size":[595.276,841.89]},"153":{"tab":"","blocks":[{"t":"p","x":"Der Fischerkönig ragte düster über dem wimmernden Alchemisten auf und verhöhnte ihn. Ein so selbstsüchtiger Sucher könne niemals des Grals würdig sein. Als Spott oder vielleicht auch Hilfe bei der Suche gab Corbin Payne Armand einen einzigen Tropfen Wasser aus dem Gral. „Geh, finde deinen Stein der Weisen“, ertönte seine spöttische Stimme, als der Alchemist durch die leeren Büroetagen des unfertigen Wolkenkratzers rannte, „du hast kaum noch Zeit ...“","sz":9.5,"box":[53.9,59.9,286.1,169.4],"p":153,"i":0,"sec":"armand-kais-geschichte"},{"t":"sh","x":"<b>DIE SUCHE NACH EINEM HEILMITTEL</b>","sz":10.0,"box":[54.3,183.0,258.7,193.0],"p":153,"i":1,"sec":"armand-kais-geschichte"},{"t":"p","x":"Nach der Begegnung mit Corbin Payne war Armand Kai besessen von der Suche nach ewigem Leben und ließ nichts unversucht. Die wenigen Entdeckungen konnten sein Leben unnatürlich verlängern, aber ihm blieb schmerzlich bewusst, dass er immer noch alterte. Die Jahre vergingen, und er sammelte arkanes Wissen und Macht, bis er es mit jedem in der Stadt aufnehmen konnte. Doch das wahre Magnum Opus, den Stein der Weisen oder Elixier des Lebens, das ihn von der Furcht vor dem Tod befreien würde, fand er nicht.","sz":9.5,"box":[53.9,198.6,284.5,320.6],"p":153,"i":2,"sec":"armand-kais-geschichte"},{"t":"p","x":"Mit jedem Jahr wuchs seine Sorge, dass die Welt ihn aufzehren würde. Jede kleine Störung kostete Zeit, die er für sein Werk brauchte, und verschwendete wertvolle Augenblicke. Die hektische Stadt war voller Bedrohungen für sein Leben, ob zufällig oder absichtlich, und überall sah er die langen, spindeldürren Finger des Todes nach ihm greifen. Er wollte alles behalten: seine Zeit, sein Wissen, seine Ressourcen, sein Leben. Die Menschen wurden zum Ärgernis, dann zur Bedrohung. Immer mehr entwickelte er sich zu einem Einsiedler (ähnlich wie Corbin Payne) und widmete sich ganz dem Streben, seinen nahenden Untergang abzuwenden. Er schloss sich im Keller von Canseliet Manor ein, zog sich in sein Versteck zurück, immer tiefer in die Erde, und umgab sich mit allen möglichen Schutzmaßnahmen.","sz":9.5,"box":[53.9,329.3,285.7,526.3],"p":153,"i":3,"sec":"armand-kais-geschichte"},{"t":"sh","x":"<b>EIN WENDEPUNKT</b>","sz":10.0,"box":[54.3,539.9,156.0,549.9],"p":153,"i":4,"sec":"armand-kais-geschichte"},{"t":"p","x":"Vor einigen Jahren, als seine Zeit fast abgelaufen war, machte Armand eine bahnbrechende Entdeckung: Mit der richtigen alchemistischen Prozedur konnte er das Gralswasser nutzen, um den Nebel abzuwaschen und neue Risse zu erwecken. Dies eröffnete die Möglichkeit, einen Riss zu finden, der ewiges Leben schenken konnte, und begründete eine neue Forschung: die Alchemie der Mythen. Aber die Erweckung war unberechenbar. Niemand konnte vorhersehen, welche Mythen beim jeweiligen Experiment erweckt wurden. Armand konnte nur in großem Maßstab ausprobieren, wofür er einen Ofen entwickelte, der den Mythos aus einem Riss herausschmelzen konnte (s. S. <i>Athanor</i>, S. 87) und einen falschen Kult gründete, der Risse in Massen erweckte, um den Ofen mit genug Rohmaterial zu versorgen (s. S. <i>Der Kult des Gottkönigs</i>, S. 113).","sz":9.5,"box":[53.9,555.4,284.6,752.4],"p":153,"i":5,"sec":"armand-kais-geschichte"},{"t":"h","x":"CINEASTISCHER DUNGEON-CRAWL","sz":14.0,"box":[320.3,61.0,481.4,75.0],"p":153,"i":6,"sec":"armand-kais-geschichte"},{"t":"p","x":"Die Erkundung eines Gebäudes in <i>City of Mist</i> unterscheidet sich von Dungeon Crawls in anderen Rollenspielen. Mit seinem cineastischen Ansatz konzentriert sich <i>City of Mist</i> auf zentrale Orte im Gebäude und Schlüsselszenen, die sich dort abspielen, statt sich Zentimeter für Zentimeter auf der Karte zu bewegen. Ähnlich wie in einem Film oder einem anderen fiktionalen Werk räumt man nur den interessanten Ereignissen Sendezeit ein.","sz":9.0,"box":[320.3,87.5,525.2,192.5],"p":153,"i":7,"sec":"armand-kais-geschichte"},{"t":"sh","x":"<b>DER BAU DES HERRENHAUSES</b>","sz":10.0,"box":[310.0,220.9,475.0,230.9],"p":153,"i":8,"sec":"armand-kais-geschichte"},{"t":"p","x":"Ehe er jedoch beides schuf, musste Armand zunächst in seinem unterirdischen Labor den Riss-Veredelungsprozess perfektionieren. Als er mit den Ergebnissen zufrieden war, baute er einen unterirdischen Komplex, der auf den vier Phasen des alchemistischen Magnum Opus basierte – Fäulnis, Läuterung, Erwachen und Transformation. Als dieser Chemiebaukasten in Gebäudegröße fertiggestellt war, schloss er sich in dessen tiefsten Kammern ein und widmete sich der Forschung, und überließ die Pflege des Anwesens seinen Schüler:innen.","sz":9.5,"box":[309.6,236.5,540.8,371.0],"p":153,"i":9,"sec":"armand-kais-geschichte"},{"t":"p","x":"Wenn jemand Armand erreichen und seine Arbeit stören möchte, musste er den alchemistischen Prozess überleben: Nur die reinsten Substanzen können zu ihm vordringen. Während der Kult und der Ofen ihr Werk fortsetzten, treibt der alte Alchemist seine Arbeit voran, sicher in seinem geheimen Labor, wo er gierig die Essenz von Hunderten von Mythen verschlingt und mit jedem Tag gefühlloser und selbstsüchtiger wird.","sz":9.5,"box":[309.6,379.6,541.0,476.6],"p":153,"i":10,"sec":"armand-kais-geschichte"},{"t":"h","x":"EINZELABENTEUER","sz":14.0,"box":[320.9,520.7,407.8,534.7],"p":153,"i":11,"sec":"armand-kais-geschichte"},{"t":"p","x":"Wenn du diesen Fall als Einzelabenteuer leitest, ist Canseliet Manor nicht nur eine Ichor-Raffinerie, sondern auch eine Falle für Risse, deren Kräfte Armand ernten will. Angelockt von Gerüchten über den Stein der Weisen, den Gral, einen Goldschatz oder arkanes Wissen wagen sich die Risse tief unter das Herrenhaus. Dabei veredelt das Gebäude sie, bis sie bereit sind, von dem Alchemisten zu geerntet zu werden.","sz":9.0,"box":[320.9,547.2,529.6,640.2],"p":153,"i":12,"sec":"armand-kais-geschichte"}],"size":[595.276,841.89]},"154":{"tab":"","blocks":[{"t":"h","x":"CANSELIET MANOR","sz":16.0,"box":[53.9,62.2,181.2,78.2],"p":154,"i":0,"skip":true,"sec":"canseliet-manor"},{"t":"p","x":"Armand erwarb Canseliet Manor einige Jahrzehnte nach seinem Erwachen mit dem Vermögen, das er durch seine Fähigkeit, andere Metalle in Gold zu verwandeln, angehäuft hatte, wohl wissend, dass das Anwesen auf einer Goldmine liegt. Was als scheinbar banales Herrenhaus begann, verwandelte er bald in eine Schule und ein Labor für Alchemie, wo er seine Suche nach Unsterblichkeit vorantrieb.","sz":9.5,"box":[53.9,83.6,276.2,180.6],"p":154,"i":1,"sec":"canseliet-manor"},{"t":"p","x":"Die größte Verwandlung erfuhr das Herrenhaus, nachdem Armand zum Gralsritter geworden war. In seinem Wahn grub der Alchemist tiefer, entschlossen, den gesamten Komplex in eine alchemistische Raffinerie zu verwandeln, die auf den Geheimnissen des Großen Werkes basierte. Später nutzte er denselben Komplex, um den Ichor zu raffinieren, den er und seine Diener:innen aus Rissen extrahiert hatten.","sz":9.5,"box":[53.9,189.3,282.4,286.3],"p":154,"i":2,"sec":"canseliet-manor"},{"t":"p","x":"Jede Schicht der Struktur steht für eine andere Phase des Raffinierungsprozesses:","sz":9.5,"box":[53.9,294.9,276.6,316.9],"p":154,"i":3,"sec":"canseliet-manor"},{"t":"p","x":"<b>Das Herrenhaus (Schicht 1) repräsentiert die erste Stufe, die Fäulnis.</b> In dieser Stufe wird der <u>Ichor destilliert</u> und geläutert. Wer diese Stufe durchläuft, muss sich seinen Schwächen und Fehlern stellen.","sz":9.5,"box":[53.9,325.7,283.0,372.6],"p":154,"i":4,"sec":"canseliet-manor"},{"t":"p","x":"<b>Die <u>Aqua-Fortis-Zisterne</u> (Schicht 2) stellt die zweite Stufe, die Läuterung, dar.</b> Eine große, mit Flüssigkeit gefüllte Höhle, die Unreinheiten wegschmilzt und über Jahrzehnte geschaffen wurde. Das Aqua Fortis reinigt den Ichor von Einflüssen des Lebens und der alten Persönlichkeit. Wer das Wasser berührt, verliert seine sterblichen Bindungen.","sz":9.5,"box":[309.0,62.6,530.0,147.0],"p":154,"i":5,"sec":"canseliet-manor"},{"t":"p","x":"<b>Die <u>Goldmine</u> (Schicht 3) steht für die dritte Stufe, das Erwachen.</b> Inzwischen ist der Ichor zur reinen Mythos-Substanz veredelt. Eine Handvoll von Armands treuesten Anhänger:innen, die Goldenen, leben hier und verarbeiten die flüchtigen Essenzen, um sie für ihren Meister vorzubereiten. Wer nicht edel wie Gold ist, riskiert hier, mit den Essenzen zu reagieren.","sz":9.5,"box":[309.0,155.8,537.7,240.2],"p":154,"i":6,"sec":"canseliet-manor"},{"t":"p","x":"Auf der untersten Ebene, in einer grob behauenen Höhle, befindet sich <b><u>Armands Labor</u> (Schicht 4), das die vierte Stufe, die Transformation, darstellt</b>. Hier forscht Armand, indem er Mythos-Essenzen in Tinkturen umwandelt und damit experimentiert, um das Geheimnis des ewigen Lebens zu ergründen. Außerdem bewahrt er hier seinen wertvollsten Schatz auf: das Gralswasser.","sz":9.5,"box":[309.0,248.8,537.6,345.8],"p":154,"i":7,"sec":"canseliet-manor"}],"size":[595.276,841.89]},"155":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 0:","sz":14.0,"box":[53.9,61.9,122.3,75.9],"p":155,"i":0,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23.0,"box":[53.9,84.2,170.2,107.2],"p":155,"i":1,"skip":true},{"t":"p","x":"Folgendermaßen kannst du das Team in den Fall einbeziehen:","sz":9.5,"box":[53.9,115.7,278.0,137.7],"p":155,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Das Team kann die Ermittlungen aus den Fällen <i>Athanor</i> und <i>Der Kult des Gottkönigs</i> fortsetzen.</b> Die Verfolgung der Ichor-Lieferungen aus der Aurora-Glashütte (s. S. 105) oder den Katakomben (s. S. 146) führt zur hinteren Laderampe von Canseliet Manor. Wenn das Team den Katakomben-Komplex stillgelegt hat, könnten sich die Jünger:innen ins Herrenhaus zurückziehen, oder der Zirkel schickt sie zur Ausbildung zum „Großen Lehrer“ (wie sie Kai nennen). Wenn das Team versucht, eine seiner Mythos-Essenzen oder die von bekannten Opfern, wie Juan Delamar, wiederherzustellen, finden sich alle notwendigen Mittel in Armands Labor.","sz":9.5,"box":[53.9,149.2,280.6,308.7],"p":155,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Auf der Suche nach Armands Schätzen</b>: Das Team kann hinter einem oder allen Schätzen Armands her sein: dem Gralswasser, dem Aqua Regia oder Aqua Fortis, den Mythos-Tinkturen (einer bestimmten oder allen), seinem enormen Goldvorrat, dem Geheimwissen usw. Die Beweggründe für einen solchen Raub können vielfältig sein. Ein krankes oder sterbendes Teammitglied könnte die anderen dazu bringen, nach einem Heilmittel zu suchen. Vielleicht muss Armand dieses brauen. Ein kriminelles Superhirn mit schlechtem Ruf könnte das Team anheuern (etwa Alex Duval). Oder eine mächtige Riss-Strippenzieher:in lässt etwas stehlen, vielleicht im Tausch gegen eine Sache, die das Team braucht.","sz":9.5,"box":[53.9,317.3,284.2,489.3],"p":155,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Ariadne</b>: Diese mysteriöse Führerin (s. S. 126) kann spirituell Suchende oder okkulte Forscher:innen auf Canseliet Manor als ein „Labyrinth“ voller Antworten hinweisen, einschließlich derer auf persönliche Mysterien oder die großen Fragen über die Stadt. Sie weiß, dass Armand kurz davor ist – wenn er es nicht schon geschafft hat –, ewiges Leben zu erlangen oder seine weltliche Existenz zu transzendieren. Sie will dieses Wissen für sich selbst oder es Armands selbstsüchtigen Klauen entreißen und anderen zugänglich machen. Außerdem liebt sie es, Held:innen in Labyrinthe zu schicken.","sz":9.5,"box":[53.9,498.0,285.9,645.0],"p":155,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Armands Einladung</b>: Der Alchemist selbst hat vielleicht von dem Team und seinen Kräften gehört und könnte an der Mythos-Essenz eines oder mehrerer Mitglieder interessiert sein. Er läd sie in sein Haus ein und bietet eine Gegenleistung. Dann lässt er sie entweder auf dem Weg zu seinem Labor „veredeln“ oder versucht, sie zu manipulieren oder zu trennen, um ihren kostbaren Ichor zu erhalten und daraus eine Tinktur herzustellen. Armand interessiert sich","sz":9.5,"box":[53.9,653.7,283.1,763.2],"p":155,"i":6,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"besonders für die Risse von Mythen, die mit Unsterblichkeit oder Langlebigkeit zu tun haben, aber auch für jede andere Kraft, die ihm bei seinen Forschungen helfen kann.","sz":9.5,"box":[317.5,59.9,541.3,106.9],"p":155,"i":7,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"<b>Das Team beginnt unabhängig von ihrer Motivation den Fall auf dem Grundstück von Canseliet Manor (s. u.)</b> Es weiß nichts über Armand, außer vielleicht, dass er ein Alchemist und der große Lehrer des Kultes des Gottkönigs ist – möglicherweise nicht einmal, ob er noch lebt. Wenn du diesen Fall als Einzelabenteuer spielst, kommt Armand vielleicht gar nicht vor, sondern nur sein mysteriöses Herrenhaus voller Schätze, die nur auf ihre Bergung warten.","sz":9.5,"box":[309.0,112.9,536.2,222.3],"p":155,"i":8,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"CANSELIET MANOR: GRUND- STÜCK UND AUSSENANLAGEN","sz":16.0,"box":[333.9,244.6,530.1,277.6],"p":155,"i":9,"skip":true,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"ro","x":"Canseliet Manor scheint verlassen, aber vielleicht ist das beabsichtigt. Efeu bedeckt das rostige schmiedeeiserne Tor, das einst vergoldet gewesen sein könnte, und windet sich um das Schloss, als wolle es euch abwehren. Eine Privatstraße, die schon bessere Tage gesehen hat, schlängelt sich durch das Dickicht zwischen den Bäumen, die sich ihrerseits dicht an sie schmiegen, um die Privatsphäre des dahinter liegenden Grundstücks zu schützen. Es ist, als wolle das Herrenhaus etwas für sich behalten, ein Geheimnis, das es nicht bereitwillig preisgibt.","sz":9.0,"box":[317.5,280.0,538.9,429.4],"p":155,"i":10,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"Dies ist eines der größten Herrenhäuser der Stadt. Trotz seiner Lage am Rande der Altstadt steht es auf einem ausgedehnten Gelände, das mit überwucherten Gärten und Wiesen bedeckt ist. Herrenhaus und Torhaus sind die einzigen Gebäude auf dem Grundstück.","sz":9.5,"box":[309.0,438.4,535.7,497.9],"p":155,"i":11,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"card","x":"Aus den <b>städtischen Unterlagen</b> geht hervor, dass die Villa einem gewissen Armand Kai gehört, aber das Kaufdatum ist verloren oder (vielleicht durch den Nebel) geschwärzt.","sz":null,"k":"yellow","box":[309.3,506.9,541.7,565.9],"p":155,"i":12,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"Auf dem Gelände gibt es mehrere Sicherheitsvorkehrungen:","sz":9.5,"box":[309.0,577.2,532.0,599.2],"p":155,"i":13,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"• Eine 3,60 m hohe und 1,80 m breite <b>Steinmauer</b> umgibt das Herrenhaus (<i>Durchbrechen: 4</i>). Das rostige, überwucherte Haupttor auf der Altstadtseite ist immer geschlossen, weil Jünger:innen Armands die beiden hinteren Servicetore auf der Wohn- bzw. Industriegebietsseite benutzen.","sz":9.5,"box":[309.0,610.8,538.5,682.8],"p":155,"i":14,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"• Die <b>Polizei</b> patrouilliert regelmäßig an der Umfassungsmauer, als Teil ihres Dienstes für die reicheren Bewohner dieses Stadtviertels. Jede verdächtige Aktivität melden die Streifenpolizist:innen sowohl dem Revier als auch dem privaten Sicherheitsdienst der Villa.","sz":9.5,"box":[309.0,691.4,537.2,763.4],"p":155,"i":15,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"}],"size":[595.276,841.89]},"156":{"tab":"","blocks":[{"t":"p","x":"• An der Umfassungsmauer, an wichtigen Stellen des Geländes und rund um das Hauptgebäude sind <b>hochwertige weltliche Sicherheitsmaßnahmen</b> wie Überwachungskameras, Bewegungsmelder und Laserschranken installiert.","sz":9.5,"box":[53.9,59.9,276.7,119.4],"p":156,"i":0,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"• Mehrere Schichten <b>alchemistischer Schutzwälle</b> halten legendäre Eindringlinge aller Art fern: Geister und körperlose Wesen können die Begrenzung nicht überschreiten, Gestaltwandler nehmen wieder ihre wahre Gestalt an, magische Transporte und Wahrsagerei sind blockiert. Dies repräsentiert der Zustand <t>Schutzzeichen 1</t> auf dem gesamten Gelände. Die Stufe erhöht sich um die Schicht des Ortes (<t>Schutzzeichen 2</t> für Schicht 1, das Herrenhaus, <t>Schutzzeichen 3</t> für Schicht 2, die Zisterne Aqua Fortis usw.) Erhöhe den Zustand um 1, wenn jemand versucht, sich direkt an einen Ort zu teleportieren (z. B. behindert <t>Schutzzeichen 6</t> ein Teleportieren in Armands Labor). Das erfolgreiche Durchdringen einer Schicht gewährt keinen Vorteil beim Durchdringen der nächsten, aber man kann davon ausgehen, dass der SC alle Schichten davor bezwungen hat.","sz":9.5,"box":[53.9,128.1,286.3,337.6],"p":156,"i":1,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"• <b>Schlummerdorn</b>, ein Strauch, der mit der Tinktur von Dornröschens Rosenhecke versetzt ist, wächst ringsum am inneren Fuß der Mauer. Bei Berührung wächst er rapide, um jegliche Bewegung zu behindern, und die arglistigen Dornen induzieren Schlaf.","sz":9.5,"box":[53.9,346.3,278.1,405.8],"p":156,"i":2,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"• Ein <b>privater bewaffneter Sicherheitsdienst</b> patrouilliert an der Umfassungsmauer, an den Toren, auf dem Gelände und rund ums Hauptgebäude. Dabei handelt es sich um <b>Jünger:innen Armands</b> in schwarzen Anzügen oder langen Mänteln, die gepanzerte Geländewagen fahren.","sz":9.5,"box":[53.9,414.4,286.3,486.4],"p":156,"i":3,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"• <b>Sickergruben für Ichor-Nebenprodukte</b> sind über das gesamte Gelände verstreut. Obwohl sie nicht als Sicherheitsmaßnahme gedacht sind, können sie unvorsichtigen Eindringlingen zum Verhängnis werden. Sie enthalten einen pechartigen Schadstoff, der mit den Gedanken, Gefühlen und Empfindungen anderer Menschen durchtränkt ist. Die Verunreinigung führt zu einem entsprechenden Zustand, z. B. <t>unerklärlich glücklich</t> oder <t>Rückenschmerzen</t>, mit einer Stufe, die dem Ausmaß des Kontakts entspricht, z. B. 2 für Berührung und 4 für Hineinfallen.","sz":9.5,"box":[53.9,495.1,282.4,629.6],"p":156,"i":4,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"card","x":"Aus den <b>städtischen Unterlagen</b> geht hervor, wie das Gelände und das Hauptgebäude angelegt sind und dass Polizeistreifen und ein privater Sicherheitsdienst zu erwarten sind. <b>Gerüchte von Kindern oder Einbrechern</b> berichten vom Schlummerdorn und den weltlichen Sicherheitsmaßnahmen. <b>Überlebende von früheren Raubüberfällen oder Magiekundige</b> (wie Ariadne) können dem Team von den Wachen und/oder Sickergruben berichten.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,188.1],"p":156,"i":5,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"card","x":"<b>Magiekundige</b> können aus der Schlummerdorn-Tinktur und den alchemistischen Schutzwällen schließen, dass Armands Alchemie legendäre Kräfte verfeinern oder ihre Manifestation verhindern kann.","sz":null,"k":"yellow","box":[309.3,197.3,541.7,268.4],"p":156,"i":6,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"card","x":"<b>Die pechartige Substanz in den Sickergruben kann man nur als vergorene Überreste einer Seele beschreiben</b>. Teammitglieder, die bereits Ichor analysiert haben, werden sie als Bestandteil davon erkennen. Wer eine Tinktur analysiert hat, kann vermuten, dass es sich um ein Nebenprodukt der Erstellung handelt.","sz":null,"k":"yellow","box":[309.3,277.6,541.7,374.1],"p":156,"i":7,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"card","x":"Die Erkundung des Herrenhauses zeigt rund um die Uhr Aktivität an der hinteren Laderampe, aber keine Bewegung vor dem Haus <u>(Foyer),</u> das verlassen zu sein scheint.","sz":null,"k":"yellow","box":[309.3,383.0,541.7,442.1],"p":156,"i":8,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"sh","x":"<b>ARMANDS GEIST WACHT</b>","sz":10.0,"box":[309.4,468.1,445.0,478.1],"p":156,"i":9,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"Sobald die Wachen aktiviert sind oder die Jünger:innen die Anwesenheit eines Eindringlings bemerken, machen sie Armand darauf aufmerksam. Er projiziert seinen Geist an den Ort, an dem sich die Eindringlinge aufhalten, sie zu durchleuchten und herauszufinden, wer sie sind und welche Essenzen sie haben. Es kann sein, dass er sich für die Mythos-Essenz eines der Teammitglieder oder ihrer Verbündete (z. B. Mondgeists Unsterblichkeit, s. S. 133) interessiert und einen Weg findet, sie von der Gruppe zu trennen. Andernfalls verfolgt er den Einbruchsversuch mit wachsender Besorgnis und bereitet Gegenmaßnahmen vor.","sz":9.5,"box":[309.0,483.7,538.2,630.7],"p":156,"i":10,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"p","x":"Nur Fähigkeiten, die Wahrsagerei entgegenwirken, können ihn hindern, ein Eindringen so wahrzunehmen (etwa Silvio Yadaos Tinktur der Tarnkappe, <i>Der Kult des Gottkönigs</i>, S. 139). Risse, die Geister sehen oder <b>Hinter den Nebel blicken</b>, bemerken vielleicht den Geist eines Mannes mittleren Alters in einem eleganten, aber ausgefallenen Anzug, der sie wütend, wie ein lästiges Ärgernis, anstarrt. Um die Projektion zum Ursprung zurückzuverfolgen, muss man den Schutzwall dazwischen durchbrechen (meist <t>Schutzzeichen 5</t>).","sz":9.5,"box":[309.0,639.4,539.7,761.4],"p":156,"i":11,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"}],"size":[595.276,841.89]},"157":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"SCHLUMMERDORN","spectra":"DURCHSCHNEIDEN 3","items":["<b>Bitte nicht stören</b>: Wenn man den Schlummerdorn zum ersten Mal stört, macht er als Einmischung eine harte Aktion.","<b>Nicht schon wieder ein Prinz</b>: Bei der Anwendung auf König:innen, Prinz:essinnen oder Ritter:innen reduzieren sich die Stufen der Zustände, die der Schlummerdorn zufügt, um 1.","Sich um die Gliedmaßen seines Opfers wickeln (<t>verheddert 3</t>)","Die Haut eines Opfers mit giftigen Stacheln zerkratzen und durchbohren (<t>schläfrig 2</t>)","Unkontrolliert wachsen und den Weg blockieren (Maximum von <i>Durchschneiden</i> um 1 erhöhen)","Eine Brise weht durch seine Blätter"],"box":[160.0,57.5,190.6,69.5],"desc":"Der Schlummerdorn wächst am Fuße der Umfassungsmauer und zwischen Bäumen auf dem Gelände. <i>Durchschneiden 3</i> ist nötig, um eine Person durch das Dickicht zu bringen. Für mehrere Personen oder einen Weg für etwas Größeres freizuschneiden, ist mehr Aufwand erforderlich (erhöhe das Maximum um den Größenfaktor dessen, was passieren soll oder lass Effekte skalieren (wie bei <b>Das Blatt wenden</b>).","p":157,"i":0,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"},{"t":"threat","stars":"★★★","name":"JÜNGER:IN ARMANDS","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3","items":["<b>Versprechen des ewigen Lebens</b>: Wenn die Jünger:in die Szene betritt, gib ihr <t>loyal 4</t>, erneuerbar als harte Aktion.","<b>Ausgebildete Alchemist:in</b>: Einmal pro Szene kann Jünger:in Armands als Einmischung eine Transmutations-Aktion ausführen.","Als Wache vor dem Herrenhaus: eine Maschinenpistole abfeuern (<t>Schusswunde 3</t>)","Alarm schlagen und mehr Jünger:innen herbeirufen (Größenfaktor +1)","Ihr Element per Transmutation verändern: » <b>Erde:</b> eine schützende Barriere errichten (<i>Zerschlagen 4</i>) oder einen Weg versperrt (<b>Ihnen etwas verweigern, das sie wollen</b>) » <b>Feuer:</b> jemanden mit Feuer angreifen (<t>verbrannt 3</t> oder <t>geblendet 3</t>) » <b>Wasser:</b> Dehydrieren (<t>dehydriert 3</t>) oder mit einem Wasserschwall angreifen (Betroffene sind temporär <t>niedergeschlagen 3</t>) » <b>Luft:</b> Kultist:innen <t>im Nebel versteckt 2</t> verleihen oder jemandem den Atem nehmen (<t>erstickend 3</t>) » <b>Blei (oder Silber):</b> Kultist:innen vor Bleigeschossen schützen (kontert die nächsten 3 Stufen Schüsse) oder Blei verschießen (<t>Schusswunde 3</t>) » <b>Eisen:</b> Gegenstände aus Stahl bewegen (<t>zermalmt 3</t>) oder zu einem Käfig verbiegen (<t>im Käfig 3</t>) » <b>Salz:</b> Eine Oberfläche mit Salz verätzen (<t>zerfressen 3</t> oder <t>Löcher 3</t>) oder Flüssigkeiten kristallisieren lassen (<t>kristallisiert 3</t>) » <b>Arsen:</b> Jemandem eine Arsenvergiftung zufügen (<t>vergiftet 3</t> und in jeder Drehpause erneut <t>vergiftet 3</t>) und zwingen, sich zu ergeben, damit die Jünger:in das Arsen wieder aus dem Körper entfernt » <b>Phosphor:</b> eine Rauchwand erzeugen (<t>Deckung 3</t> oder <b>Ihnen etwas verweigern, das sie wollen</b>) oder <t>chemische Verbrennungen 3</t> verursachen","Ihren täglichen Aufgaben nachgehen und dabei dem Team in die Quere kommen","Glühende Sigillen in die Luft zeichnen, die das gewählte Element anziehen","Über diejenigen spotten, die die Macht des großen Lehrers unterschätzen"],"box":[172.8,295.2,203.4,307.2],"desc":"Wenn du den Fall als Teil der mystischen Ebene spielst, können Jünger:innen Armands Magnum- Opus-Absolvent:innen sein – einige vielleicht Leute, die das Team nicht davor bewahren konnte, dem Kult beizutreten. Andernfalls sind sie aufstrebende Alchemist:innen, die ihm folgen. Die Jünger:innen leben in der Villa und unterstützen Armand, in der Hoffnung, mehr von ihm zu lernen. Im Gegenzug für ihre Dienste unterrichtet er sie in Transmutationen, die es ermöglichen, ein oder mehrere Elemente zu kontrollieren. Eine Jünger:in trägt oft einen Vorrat ihres Elements bei sich, wenn es nicht allgegenwärtig ist.<br><br>Im Gegensatz zu den Magnum-Opus-Jünger:innen (s. S. 121) haben Jünger:innen Armands kein Kadavergehorsam und machen sich keine Illusionen darüber, was Armand tut. Sie sind hier, weil er ihnen arkane Macht und ewiges Leben verspricht, sind vielleicht verärgert darüber, wie lange es dauert, dies zu erreichen. Wenn jemand einen kürzeren Weg bietet, indem sie sich gegen Armand wenden, könnten sie das Angebot annehmen. Um dies widerzuspiegeln haben sie kein <i>Abkehr</i>-Spektrum. Man kann sie mit einer erfolgreichen <b>Überzeugen</b>-Aktion umstimmen, wenn man ihre Loyalität erschüttert.<br><br>Jünger:innen Armands tragen Schutzanzüge und Laborkittel, wenn sie Experimente durchführen oder in der Ichor-Destillerie arbeiten, schwarze Anzüge als Sicherheitskräfte fungieren und legere Kleidung, wenn sie in ihrem Quartier eine Pause einlegen.","p":157,"i":1,"sec":"canseliet-manor-grund-stueck-und-aussenanlagen"}],"size":[595.276,841.89]},"158":{"tab":"","blocks":[],"size":[595.276,841.89]},"159":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 1:","sz":14.0,"box":[53.9,61.9,120.8,75.9],"p":159,"i":0,"skip":true,"sec":"schicht-1-das-herrenhaus"},{"t":"h","x":"DAS HERRENHAUS","sz":23.0,"box":[53.9,84.2,226.9,107.2],"p":159,"i":1,"skip":true},{"t":"p","x":"Das Hauptgebäude ist ein altes, dreistöckiges Herrenhaus, das auf einem idyllischen Hügel inmitten von überwucherten Gärten liegt. Es ist weitgehend von der Außenwelt abgeschirmt.","sz":9.5,"box":[53.9,115.7,282.7,162.7],"p":159,"i":2,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"Im Inneren ist die Luft erfüllt vom Mief verwesender und gärender Substanzen, die zum Teil von Verunreinigungen stammen, die in der <u>Ichor-Destillerie</u> verfaulen, oder vom übel riechenden Dreck des Eurynomos, der verrottenden Kreatur, die das <u>Foyer</u> bewacht.","sz":9.5,"box":[53.9,171.3,284.9,230.8],"p":159,"i":3,"sec":"schicht-1-das-herrenhaus"},{"t":"card","x":"FOYER","sz":null,"k":"yellow","box":[44.6,241.3,146.3,264.4],"p":159,"i":4,"sec":"schicht-1-das-herrenhaus"},{"t":"ro","x":"Das Foyer, einst prächtig und beeindruckend, liegt in Trümmern. Es ist von einer Schicht pechschwarzen Drecks bedeckt, die nach verfaultem Fleisch, Schimmel, Fäkalien und allen anderen nur denkbaren Gerüchen stinkt. Ihr schaffte es mit Mühe, euch nicht zu übergeben, als der dunkle Schlamm sich in Bewegung setzt und langsam in die Mitte des Raumes schlittert, wo er sich zu einer massigen Kreatur formt, die euch aus roten Facettenaugen anstarrt. Euer Mittagessen bei euch zu behalten wird zur echten Herausforderung.","sz":9.0,"box":[62.4,265.9,283.8,415.3],"p":159,"i":5,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"Der Haupteingang führt durch eine hohe Doppeltür ins Foyer. Dieses ist mit einer Doppeltreppe ausgestattet, die zu einer Galerie im ersten Stockwerk führt, die mit dem Rest des <u>Verlassenen Hauses</u> verbunden ist, ebenso wie die Türen zu den Seiten im Erdgeschoss. Eine Tür auf der gegenüberliegenden Seite führt zu den Dienstbotenräumen, die heute als <u>Quartiere der Jünger:innen</u> dienen.","sz":9.5,"box":[53.9,424.3,285.6,521.3],"p":159,"i":6,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"Die rissigen Marmorböden, mit Teppich ausgelegten Stufen und die abblätternden Wände sind mit Dreck bedeckt, dem Nebenprodukt des Wächters dieses Ortes. Den <b>Eurynomos</b> (ein griechischer Dämon der Unterwelt oder Geist der Fäulnis) hat Armand beschworen, um sich mit der nützlichen Fähigkeit, Fäulnis hervorzurufen, helfen zu lassen. Der Geist dient seinem Meister, indem er den Zersetzungsprozess in der <u>Ichor-Destillerie</u> beschleunigt, hält sich aber ansonsten im Foyer auf, als Sicherheitsmaßnahme und in der Absicht, den <b>alchemistischen Prozess der Fäulnis</b> aller Risse einzuleiten, die sich ins Haus wagen: sie zu zwingen, all ihre negativen Aspekte auszuspucken und sich ihnen zu stellen.","sz":9.5,"box":[53.9,529.9,285.5,701.9],"p":159,"i":7,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"Um Risse zu beeinflussen, muss sich der Dämon materialisieren, als massiver, menschenähnlicher und knapp 4 Meter hoher Haufen schwarzer, zerfallender Materie mit roten Facettenaugen und violetter Haut, die manchmal durch die verrottenden Schichten zu se-","sz":9.5,"box":[53.9,710.6,284.9,770.1],"p":159,"i":8,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"hen ist. Wie bei der Spezialaktion <b>Verwesung</b> erklärt, bringt die Anwesenheit des Eurynomos Schwächen, Fehler, emotionalen Ballast und Dunkelheit in einem Individuum zum Vorschein, was zu explosiven Geständnissen führt, wie zum Beispiel:","sz":9.5,"box":[309.0,62.5,534.5,122.0],"p":159,"i":9,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"• „Ich wollte alle verraten und das Lebenselixier für mich behalten.“ • „Ja, ich genieße das Töten. Es gibt keinen größeren Nervenkitzel. Ich bin ein Tier.“ • „Ich bin nur zu allen nett, weil ich Angst habe, nicht gemocht zu werden. Ich verheimliche immer, was ich wirklich denke.“","sz":9.5,"box":[309.0,127.8,540.6,212.3],"p":159,"i":10,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"Das Eingeständnis der eigenen dunklen Seite kann vor sich oder anderen erfolgen, aber alle hören oder sehen es. Es muss Ausdruck <b>echter Reue</b> sein. Ein leichtfertiges Eingeständnis von Fehlern gilt als Widerstand gegen die Aktion <b>Verwesung</b>. Außerdem quellen Erbrochenes, Eiter oder Galle aus dem Körper des SC.","sz":9.5,"box":[309.0,218.2,538.0,290.2],"p":159,"i":11,"sec":"schicht-1-das-herrenhaus"},{"t":"p","x":"Die Jünger:innen werfen besiegte Risse in die <u>Aqua- Fortis-Zisterne,</u> auf die Straße oder töten sie – je nachdem, was Armand befiehlt.","sz":9.5,"box":[309.0,298.8,540.3,333.3],"p":159,"i":12,"sec":"schicht-1-das-herrenhaus"},{"t":"card","x":"Der <b>Eurynomos</b> ist die Essenz der Verwesung, ein Konstrukt, das Armand in seinem alchemistischen Prozess dient, ähnlich einem Homunkulus.","sz":null,"k":"yellow","box":[309.3,341.6,541.7,400.3],"p":159,"i":13,"sec":"schicht-1-das-herrenhaus"},{"t":"card","x":"<b>Der mit Emotionen aufgeladene Dreck stammt nicht vom Eurynomos, sondern von den Menschen, mit denen er zu tun hatte.</b> Manchmal finden sich darin verschmutzte Gegenstände und Erinnerungsstücke, die im Zusammenhang mit den Geständnissen stehen.","sz":null,"k":"yellow","box":[309.3,409.5,541.7,493.3],"p":159,"i":14,"sec":"schicht-1-das-herrenhaus"},{"t":"card","x":"Wer sich in der alchemistischen Tradition auskennt (s. S. <i>Der Kult des Gottkönigs</i>, S. 130), kann den Eurynomos mit der <b>Schwärzungsoder Fäulnisstufe</b> des alchemistischen Großen Werkes in Verbindung bringen.","sz":null,"k":"yellow","box":[309.3,502.6,541.7,573.7],"p":159,"i":15,"sec":"schicht-1-das-herrenhaus"},{"t":"card","x":"Um am Eurynomos vorbeizukommen, muss man sein schlimmstes Versagen zugeben (s. S. Aktion <b>Bereits verfault</b>) oder ihn mit persönlichen Fehlern besänftigen.","sz":null,"k":"yellow","box":[309.3,582.9,541.7,642.0],"p":159,"i":16,"sec":"schicht-1-das-herrenhaus"}],"size":[595.276,841.89]},"160":{"tab":"","blocks":[{"t":"threat","stars":"★★★★","name":"EURYNOMOS","spectra":"IN STÜCKE REISSEN 6 / BANNEN 6 / BESCHWICH- TIGEN 3","items":["<b>Der einzige Ausweg ist hindurch</b>: Als Einmischung kann der Eurynomos die Türen des Foyers versiegeln (<i>Zerschmettern 5</i> und <t>Schutzzeichen 2</t>).","<b>Ungeheuerlich</b>: Wenn der Eurynomos einen Zustand erlangt, den seine Größe abwehren kann, reduziert sich die Stufe um 1. Wenn die SL eine harte Aktion mit dem Eurynomos macht, kann er zwei Ziele oder ein einzelnes Ziel mit +1 Stufe treffen.","<b>Wiederaufbau</b>: Wenn der Maximalwert für <i>In Stücke reißen</i> erreicht ist, baut sich der Eurynomos wieder auf. Entferne als weiche Aktion eine Stufe, bis es keine Zustände des Spektrums mehr gibt. Der Eurynomos kann dann wieder handeln.","<b>Verwesung</b>: Als weiche Aktion kann die SL eine Spieler:in fragen: „Was ist der größte Fehler, die dunkelste Seite oder das größte Verbrechen deines Charakters?“ Die Spieler:in muss wahrheitsgemäß antworten. Die Gegenwart des Eurynomos zwingt den SC, dies zu gestehen. Wenn er sich weigert, erleidet er <t>emotionaler Kampf 3</t>. Gesteht er seinen Fehler ein, erhält er <t>gedemütigt 5</t>, der Eurynomos nimmt <t>besänftigt 1</t>, und die SL kann eine harte Aktion machen, um die Konsequenzen abzubilden.","<b>Bereits verfault</b>: Der Eurynomos ignoriert die, die die Fäulnis, durchlaufen haben, wie z. B. ein SC, der seine Schuld eingestanden hat, sowie Absolvent:innen der Silo-Prüfung (<i>Der Kult des Gottkönigs</i>, S. 135).","<b>Lass es los</b>: Vom Eurynomos erhaltene Zustände kann man sich mit dem Aqua Fortis in der <u>Aqua- Fortis-Zisterne</u> abwaschen. Für jede Stufe, die der SC <t>nass</t> wird, entfernt er eine Stufe von allen Zustandswerten, die der Eurynomos zugefügt hat.","Materie faulen lassen, um Dinge zu zerstören (verbrennt bis zu 2 Stärken) oder einen Teils der Galerie zum Einsturz bringen (<t>unter Trümmern begraben 3</t>)","Jemanden mit einer übergroßen Pranke quer durch das Foyer oder auf die Empore stoßen (<t>atemlos 4</t>)","Jemanden mit Wundbrand infizieren (<t>brandiges Körperglied 2</t>)","Einen unerträglichen Gestank verströmen, der den ganzen Raum erfüllt (<t>Übelkeit 2</t>)","Sich entmaterialisieren und in einen anderen Teil des Hauses fliehen, vor allem, wenn er kurz davor ist, verbannt zu werden (<b>Ihnen etwas verweigern, das sie wollen</b>)","Materialisieren, wobei sich Klumpen verrottenden Stoffs zusammenfügen","Mit einem schlabbrigen Körperglied auf jemanden zielen, um Fäulnis hervorzurufen"],"box":[129.8,61.7,170.6,73.7],"p":160,"i":0,"sec":"schicht-1-das-herrenhaus"},{"t":"h","x":"DAS VERLASSENE HAUS","sz":16.0,"box":[334.8,68.9,489.5,84.9],"p":160,"i":1,"skip":true,"sec":"das-verlassene-haus"},{"t":"ro","x":"Ihr betretet einen weiteren Raum der Villa und findet ihn in demselben Zustand vor wie die anderen: Einst prächtige Möbel sind tief unter einer dicken Staubschicht begraben. Knochenweiße Laken und Vorhänge flattern wie Geister der Vergangenheit im Wind, der durch die Bodenritzen weht. Wer hier gelebt hat ist längst tot und vergessen. Es bleibt nur noch eine flüchtige Erinnerung.","sz":9.0,"box":[317.5,87.3,538.9,193.5],"p":160,"i":2,"sec":"das-verlassene-haus"},{"t":"p","x":"Die meisten Räume an der Vorderseite des Hauses und fast alle über dem Erdgeschoss sind seit Jahren verfallen. Dieser Ort dient als Illustration der Geschichte Armand Kais und unheimliche Kulisse, um den Jünger:innen auszuweichen. Es könnte ein guter Ort für eine Aufklärungsmission vor einem Raubzug sein, wie ihn Verbündete des Teams vorschlagen würden. Du kannst ihn in einer Rückblende erkunden lassen.","sz":9.5,"box":[309.0,202.5,540.6,299.5],"p":160,"i":3,"sec":"das-verlassene-haus"},{"t":"p","x":"Beim Durchstreifen des Hauses findet das Team Gänge und Treppen, die mit dem <u>Foyer,</u> den <u>Quartieren der Jünger:innen</u> und der <u>Ichor-Destillerie</u> im Erdgeschoss verbunden sind (und über eine versteckte Tür sogar mit der <u>Aqua-Fortis-Zisterne).</u>","sz":9.5,"box":[309.0,308.1,538.6,367.6],"p":160,"i":4,"sec":"das-verlassene-haus"},{"t":"p","x":"Die Sicherheitsvorkehrungen rund um das Herrenhaus sind im Vergleich zum Rest des Komplexes lax:","sz":9.5,"box":[309.0,376.3,538.5,398.3],"p":160,"i":5,"sec":"das-verlassene-haus"},{"t":"p","x":"• <b>Das Haus ist gegen magisches Eindringen von außen mit einem <t>Schutzzeichen 2</t> versehen,</b> aber sobald sich jemand im Gebäude befindet, kann er ungehindert herumlaufen und seine Kräfte einsetzen, mit einer Ausnahme: Täuschungsmagie stößt immer noch auf den Widerstand des Schutzzeichens.","sz":9.5,"box":[309.0,409.8,541.4,481.8],"p":160,"i":6,"sec":"das-verlassene-haus"},{"t":"p","x":"• <b>Bewegungsmelder und Laserschranken</b> sind im ganzen Haus verteilt.","sz":9.5,"box":[309.0,490.5,527.8,512.5],"p":160,"i":7,"sec":"das-verlassene-haus"},{"t":"p","x":"• <b>Das Sicherheitsteam der Jünger:innen</b> ist auch für diesen Bereich zuständig, aber es kommt nur her, wenn jemand Alarm oder die Schutzzeichen auslöst.","sz":9.5,"box":[309.0,521.1,539.7,555.6],"p":160,"i":8,"sec":"das-verlassene-haus"},{"t":"p","x":"Der Zweck der Sicherheitsmaßnahmen ist es, die Spannung aufrechtzuerhalten, während das Team Beweise sammelt. Lass sie weg, wenn sie unnötig und langweilig wären.","sz":9.5,"box":[309.0,561.5,541.3,608.5],"p":160,"i":9,"sec":"das-verlassene-haus"},{"t":"card","x":"Alles im Haus ist mit Laken, Staub oder Schimmel bedeckt. Anhand von Einrichtung, Staubmenge oder mit einer legendären Weissagung kann man schließen, dass der <b>größte Teil des Hauses schon seit Jahrzehnten ungenutzt ist</b>.","sz":null,"k":"yellow","box":[309.3,615.5,541.7,686.9],"p":160,"i":10,"sec":"das-verlassene-haus"}],"size":[595.276,841.89]},"161":{"tab":"","blocks":[{"t":"card","x":"<b>Der Eigentümer interessierte sich für das Okkulte und Paranormale</b>, wie die Bücher im Lesesaal und der Bibliothek beweisen. Die wertvollen Texte sind längst verschwunden, es klaffen Lücken in den Regalen.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,125.6],"p":161,"i":0,"sec":"das-verlassene-haus"},{"t":"card","x":"<b>Hinter einer versteckten Tür in der Bibliothek</b> befindet sich eine steinerne Wendeltreppe, die zur <u>Aqua-Fortis-Zisterne</u> hinunterführt.","sz":null,"k":"yellow","box":[54.1,134.8,286.6,180.9],"p":161,"i":1,"sec":"das-verlassene-haus"},{"t":"card","x":"Im Büro befindet sich in einem Tresor hinter einem Gemälde die Besitzurkunde für das Haus. <b>Daraus geht hervor, dass Armand Kai die Villa vor fast einem Jahrhundert gekauft hat</b> (das Datum ist verschmiert, aber das Jahrzehnt ist erkennbar). Wenn man dies mit den städtischen Aufzeichnungen vergleicht, aus denen hervorgeht, dass Armand noch der Eigentümer ist, <b>dann ist er weit über 100 Jahre alt</b>.","sz":null,"k":"yellow","box":[54.1,190.1,286.6,311.6],"p":161,"i":2,"sec":"das-verlassene-haus"},{"t":"card","x":"<b>Es gibt Bilder von Armand als Jüngling und als Mann mittleren Alters, die hier hängen, als hätte er das Interesse an seinem frühen Leben verloren.</b> Er hat ein langes Gesicht und dunkles Haar, eine römische Nase und einem Schnurr- oder Spitzbart.","sz":null,"k":"yellow","box":[54.1,320.5,286.6,404.4],"p":161,"i":3,"sec":"das-verlassene-haus"},{"t":"card","x":"Ein Vergleich der Porträts über die Jahrzehnte, insbesondere durch eine Historiker:in, zeigt, dass <b>der Alterungsprozess irgendwann in den 50er Jahren aufgehört oder sich verlangsamt hat</b>. Danach gibt es nicht mehr viele Porträts.","sz":null,"k":"yellow","box":[54.1,413.6,286.6,485.0],"p":161,"i":4,"sec":"das-verlassene-haus"},{"t":"card","x":"<b>Psychometrie oder Retrokognition (oder andere Formen der Wahrsagung) können Fragmente von Armands Geschichte enthüllen:</b> seine Zeit an der Universität, das Interesse am Paranormalen und dann eine verzweifelte Besessenheit von der Alchemie.","sz":null,"k":"yellow","box":[54.1,494.2,286.6,578.0],"p":161,"i":5,"sec":"das-verlassene-haus"},{"t":"p","x":"Auf einem der Bilder aus Armands Uni-Zeit ist er mit anderen Wissenschaftler:innen zu sehen, die an der Erforschung des Geistes und des Paranormalen beteiligt waren. Eine der Personen auf dem Bild ist Krystal Knight (die das Team vielleicht als Dr. Esther Monahan kennt, s. <i>Scherben</i>, S. 73).","sz":10.0,"box":[62.4,592.7,271.7,677.8],"p":161,"i":6,"sec":"das-verlassene-haus"},{"t":"h","x":"KLEINE PAUSE GEFÄLLIG?","sz":14.0,"box":[320.3,61.7,440.4,75.7],"p":161,"i":7,"sec":"das-verlassene-haus"},{"t":"p","x":"In der oberen Etage, in einem der entlegensten Zimmer, stößt das Team vielleicht auf Anabelle, eine Jünger:in, die sich hierher geschlichen hat, um es sich bequem zu machen: Sie macht ein Nickerchen in dem alten, aber sehr bequemen Doppelbett im Hauptschlafzimmer. Das Team kann sie entdecken und die Indiskretion auszunutzen, um Antworten zu erhalten oder sie dazu bringen, eine Aufgabe zu erledigen. Anabelle kann jeden Hinweis verraten, den die Jünger:innen in dieser Schicht kennen.","sz":9.0,"box":[320.3,88.2,529.7,205.2],"p":161,"i":8,"sec":"das-verlassene-haus"},{"t":"h","x":"QUARTIER DER JÜNGER:INNEN","sz":16.0,"box":[334.8,253.1,534.7,269.1],"p":161,"i":9,"skip":true,"sec":"quartier-der-juenger-innen"},{"t":"ro","x":"Der Korridor erstreckt sich tief in das Haus, nur flackernde elektrische Lichter weisen euch den Weg. Weiter vorn hört man Geplauder und Gelächter, das von den alten Steinmauern widerhallt. Ihr kommt zu einer Holztür und lugt vorsichtig um die Ecke. In der ehemaligen Küche des Anwesen sitzt eine Handvoll Männer und Frauen um einen schlichten Holztisch und essen, einige als Wachleute gekleidet, andere in Arbeitsklamotten. Ihre Hände sind mit seltsamen Verätzungen übersät.","sz":9.0,"box":[317.5,271.5,538.9,399.3],"p":161,"i":10,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"Die Jünger:innen, die die <u>Ichor-Destillerie</u> betreiben und das Gelände bewachen, wohnen in den alten Bedienstetenquartieren in der Mitte des Anwesens, zwischen den leeren herrschaftlichen Räumen (dem <u>Verlassenen Haus)</u> und der <u>Ichor-Destillerie</u> im hinteren Teil. Dieser Gebäudeteil umfasst:","sz":9.5,"box":[309.0,408.3,535.4,480.3],"p":161,"i":11,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"• eine Reihe spartanisch eingerichteter <b>Schlafräume</b> mit ein oder zwei einfachen Betten und einem Nachttisch mit Lampe; • eine <b>kleine Kantine</b>, in der bis zu zwanzig Menschen Platz finden; • <b>Labore</b> für Experimente, um in der Freizeit alchemistisches Können zu verfeinern; • einen <b>Wachraum</b> mit einer Reihe von Überwachungsmonitoren; • einen Keller, der in <b>Zellen</b> unterteilt ist, in denen die landen, die beim Schnüffeln erwischt werden.","sz":9.5,"box":[309.0,486.1,540.0,620.6],"p":161,"i":12,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"In diesem Teil des Hauses bewegen sich die Jünger:innen bei ihrer täglichen Routine ständig hin und her. Daher sind die modernen Sicherheitsmaßnahmen gering. Stattdessen sind die Türen, die zu diesem Komplex führen, sowie die Innentüren zu den Labors, dem Wachraum und Arrestzellen mit <b>alchemistischen Schlössern</b> ausgestattet. Um sie zu öffnen muss man ein, zwei oder gar drei verschiedene alchemistische Elemente auf komplizierte Weise manipulieren (die Schlösser rasten beim Schließen der Tür wieder ein). Wer alle erforderlichen Transmutationen beherrscht","sz":9.5,"box":[309.0,632.2,540.2,766.7],"p":161,"i":13,"sec":"quartier-der-juenger-innen"}],"size":[595.276,841.89]},"162":{"tab":"","blocks":[{"t":"p","x":"(oder mehrere Personen zusammen), kann sie leicht öffnen. Jeder andere braucht Spezialwerkzeuge, z. B. einen Strohhalm für Luft, brennbares Gas für Feuer, einen Magneten für Metall oder starke telekinetische Fähigkeiten. Die Türen sind mit einer Stufe für jedes benötigte Element <t>verschlossen</t> und bestehen aus metallbeschlagenem Holz (<i>Durchbrechen: 4</i>). Die Arrestzellen sind zusätzlich mit einem <t>Schutzzeichen 5</t> versehen.","sz":9.5,"box":[53.9,59.9,282.6,169.4],"p":162,"i":0,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"Die Jünger:innen arbeiten als Sicherheitsleute oder in der <u>Ichor-Destillerie.</u> Einige haben von Ichorspritzern seltsame Verbrennungen an den Händen. Sie wissen, wie die Sicherheit (Schicht 0) und die Destillerie funktionieren (s. S. dort).","sz":null,"k":"yellow","box":[54.1,187.5,286.6,258.6],"p":162,"i":1,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"<b>Jünger:innen Armands kommunizieren nur in Notfällen direkt mit ihm.</b> Sie erfüllen ihre Aufgaben und erhalten im Gegenzug eine neue Rezeptur oder ein neues Experiment von ihrem Meister.","sz":null,"k":"yellow","box":[54.1,267.8,286.6,339.3],"p":162,"i":2,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"<b>Etwa einmal im Monat kommt über den Kessel an der Kette ein Rezept aus den Ebenen unter der <u>Aqua-Fortis-Zisterne</u> herauf.</b> Es ist immer in ein Blatt Gold geätzt. Die Jünger:innen bewahren die Rezepte im Labor auf.","sz":null,"k":"yellow","box":[54.1,348.5,286.6,419.6],"p":162,"i":3,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"Wenn man die Rezepte durchsucht oder die Jünger:innen aufquetscht, stellt man fest, dass <b>Armand niemals die Transmutation von Gold lehrt</b> (denn Gold kann man nutzen, um die <u>Aqua-Fortis-Zisterne</u> zu durchqueren).","sz":null,"k":"yellow","box":[54.1,428.8,286.6,500.3],"p":162,"i":4,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"<b>Einige der Jünger:innen sind ungeduldig und würden die Ausbildung gerne beschleunigen.</b> Sie ziehen in Erwägung, den Großen Lehrer aufzusuchen und ihn zu bitten, sein Wissen zu teilen. Vielleicht könnten sie dem Team helfen.","sz":null,"k":"yellow","box":[54.1,509.5,286.6,580.6],"p":162,"i":5,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"<b>Eine Handvoll Jünger:innen weiß von der versteckten Treppe, die die Bibliothek im <u>verlassenen Haus</u> mit der <u>Aqua-Fortis-Zisterne</u> verbindet.</b> Sie halten die Information nicht für wichtig, weil sie glauben, es gäbe keine Möglichkeit, an der Zisterne vorbeizukommen.","sz":null,"k":"yellow","box":[54.1,589.8,286.6,673.6],"p":162,"i":6,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"<b>Die Quelle der Kräfte der Jünger:innen ist Armand.</b> Wenn er stirbt, verlieren sie ihre Kräfte. Das ist der Grund für ihre unverbrüchliche Loyalität.","sz":null,"k":"yellow","box":[54.1,682.8,286.6,741.6],"p":162,"i":7,"sec":"quartier-der-juenger-innen"},{"t":"h","x":"PELICAN","sz":12.0,"box":[317.5,61.6,360.1,73.6],"p":162,"i":8,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"In einer Zelle oder getarnt unter den Jünger:innen befindet sich der Meisterschmuggler <b>Benjamin Pelican</b> (Schläfer, der bald als Riss Henets, der Pelikangöttin, die in der ägyptischen Mythologie die Seelen im Jenseits beschützt, erwachen wird), der wegen der Schätze hier ist. Er ist ein kräftiger Mann Ende zwanzig, der normalerweise eine wattierte Weste über einem ölverschmierten Flanellhemd, Cargohose und Wanderschuhe trägt.","sz":9.0,"box":[317.5,80.6,532.9,185.6],"p":162,"i":9,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"Pelican ist ein erfahrener Schmuggler, aber auch ein Krimineller, der erst handelt und dann denkt und nur selten einen Plan hat. Vor kurzem bemerkte er die Ichor-Ladung, die durch das Hintertor in die Villa kam, rollte sich unter dem Tor durch und schlich sich an der Achse des Wagens hängend ein. Er stahl die Kleidung eines Jüngers und schnüffelte eine Weile in den Quartieren herum, kam aber beim Öffnen der alchemistischen Schlösser nicht weiter. Entweder ist er immer noch auf freiem Fuß oder sitzt in einer Zelle.","sz":9.0,"box":[317.5,194.6,529.7,311.6],"p":162,"i":10,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"Auf den ersten Blick ist Pelican nur ein Schläfer, der in etwas verwickelt ist, das weit über seine Vorstellungskraft hinausgeht. Das Team kann ihm helfen, aber jede Entscheidung hat Folgen. Je mehr er sieht und besonders, wenn er mit dem Aqua-Fortis in Berührung kommt, desto mehr erwacht er und könnte Armand auf dem Weg zum Lebenselixier helfen. Denn wenn er Seelen sicher durch die Unterwelt bringen kann, wer sagt, dass es nicht auch rückwärts geht?","sz":9.0,"box":[317.5,320.6,532.2,425.6],"p":162,"i":11,"sec":"quartier-der-juenger-innen"},{"t":"sh","x":"<b>PELICAN</b>","sz":12.0,"box":[320.3,449.9,374.1,461.9],"p":162,"i":12,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"<i>Verbündeter</i>","sz":10.0,"box":[320.3,471.6,378.5,481.6],"p":162,"i":13,"sec":"quartier-der-juenger-innen"},{"t":"h","x":"IDENTITÄT","sz":10.0,"box":[320.3,493.1,366.6,503.1],"p":162,"i":14,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"Ich will meinen Anteil.","sz":9.0,"box":[320.3,507.8,407.3,516.8],"p":162,"i":15,"sec":"quartier-der-juenger-innen"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[320.3,528.6,360.9,538.6],"p":162,"i":16,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"<b><i>Meisterschmuggler</i></b>, <i>Erfahrener Pilot und Fahrer</i>, <i>(legendär) Schutz im Jenseits</i>, <i>profitorientiert</i>, <i>Straßenkampf</i>, <i>Schnelles Verstecken</i>, <i>(legendär) Blick ins Jenseits</i>, <i>Unerwartetes Fahrzeug</i>, <i>Schwarzmarktverbindungen</i>, <i>Herz aus Gold</i>","sz":null,"k":"yellow","box":[320.5,542.0,531.6,600.2],"p":162,"i":17,"sec":"quartier-der-juenger-innen"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[320.3,612.1,377.2,622.1],"p":162,"i":18,"sec":"quartier-der-juenger-innen"},{"t":"card","x":"<i>Ahnungsloser Schläfer</i>, <i>Hält sich nie an einen Plan</i>, <i>Zu selbstsicher</i>, <i>Auf frischer Tat ertappt</i>","sz":null,"k":"yellow","box":[320.5,625.5,516.7,647.7],"p":162,"i":19,"sec":"quartier-der-juenger-innen"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[320.3,659.6,427.0,669.6],"p":162,"i":20,"sec":"quartier-der-juenger-innen"},{"t":"p","x":"<b>Deine Zeit ist noch nicht gekommen (legendär):</b> Wenn jemand einen tödlichen Zustand der Stufe 6 erhält, kann Pelican ihn auf Stufe 5 reduzieren. Ersetze dieses Thema (entferne es, wenn es ein temporäres Thema ist).","sz":9.0,"box":[320.3,674.3,529.8,731.3],"p":162,"i":21,"sec":"quartier-der-juenger-innen"}],"size":[595.276,841.89]},"163":{"tab":"","blocks":[{"t":"h","x":"ICHOR-DESTILLERIE","sz":16.0,"box":[79.7,68.9,211.7,84.9],"p":163,"i":0,"skip":true,"sec":"ichor-destillerie"},{"t":"ro","x":"Der ätzende Fäulnisgestank wird stärker, je mehr man sich der gewölbten Halle nähert, die vielleicht einmal ein angebauter Stall oder eine Fahrzeughalle war und jetzt als Brennerei dient. Reihenweise stehen Fässer auf Metallrosten und kochen und blubbern über schwarzem und violettem, unirdischem Feuer. Dazwischen laufen Arbeiter:innen in neongrünen Schutzanzügen und mit Atemmasken umher und überwachen den Prozess. In den Dämpfen, die aufsteigen, vermeint man Bilder von Held:innen, Monstern und Zauber:innen zu sehen. Vielleicht solltet ihr nicht zu viel von diesem Zeug einatmen.","sz":9.0,"box":[62.4,87.3,283.8,247.5],"p":163,"i":1,"sec":"ichor-destillerie"},{"t":"p","x":"Ichor, das Produkt des Mythos-Ernteprozess, beginnt hier seine Veredelung. Ob er aus der alten Aurora- Glashütte (<i>Athanor</i>, S. 105), den Katakomben (<i>Der Kult des Gottkönigs</i>, S. 146) oder Opfern des Aqua Regia (Schicht 4) stammt, Armand muss ihn destillieren, bevor er ihn zu einer Tinktur verarbeiten kann. <b>Das ist der erste Schritt des alchemistischen Werks: die Fäulnis, das Entfernen der Unreinheiten.</b>","sz":9.5,"box":[53.9,256.5,284.3,353.6],"p":163,"i":2,"sec":"ichor-destillerie"},{"t":"p","x":"Die Destillerie verfügt über drei Laderampen an der Rückseite des Hauses und eine Tür, die zu den <u>Quartieren der Jünger:innen</u> führt. Diese laden den von draußen kommenden Ichor an der Andockstelle ab und transportieren ihn per Gabelstapler oder Karren zu den Flammen in der Brennerei. Die dunklen Flammen bewirken einen magischen Fäulnisprozess. Sie existieren dank des Eurynomos, eines Fäulnisdämons, den Armand zu diesem Zweck beschworen hat (s. S. <u>Foyer).</u> Der Eurynomos ist im Haus präsent, kann aber die Flammen als weiche Aktion anfachen, ohne sich zu materialisieren, es sei denn, etwas löscht aktiv die Brände.","sz":9.5,"box":[53.9,362.1,286.0,521.6],"p":163,"i":3,"sec":"ichor-destillerie"},{"t":"p","x":"Die Jünger:innen in der Destillerie dienen als Wächter:innen (<t>aufmerksam 1</t>) oder Arbeiter:innen (<t>abgelenkt 1</t>). Wenn sie einen Eindringling entdecken, rufen sie den Eurynomos zu Hilfe.","sz":9.5,"box":[53.9,530.3,279.5,577.3],"p":163,"i":4,"sec":"ichor-destillerie"},{"t":"sh","x":"<b>ICHOR</b>","sz":10.0,"box":[54.3,590.9,89.9,600.9],"p":163,"i":5,"sec":"ichor-destillerie"},{"t":"p","x":"<b>Ichor ist die unraffinierte Essenz eines Mythos.</b> Einmal geerntet, ist er stabil und inaktiv, wenn auch hochgradig korrosiv (<t>chemische Verbrennungen</t>, deren Stärke von der Exposition abhängt. Es gibt jedoch keine Mythos-Reaktion wie auf S. 86 beschrieben). Wenn man den Ichor im Feuer des Eurynomos erhitzt, trennt sich der Mythos von allen verbliebenen mentalen, emotionalen, physischen und spirituellen Assoziationen seines früheren Risses. Das Abfallprodukt sammeln die Jünger:innen in mit Blei ausgekleideten Fässern und entsorgen es auf dem Gelände oder verfüttern es an den Eurynomos, während sie die destillierte Substanz in einem schmiedeeisernen Kessel","sz":9.5,"box":[53.9,606.6,281.5,766.0],"p":163,"i":6,"sec":"ichor-destillerie"},{"t":"p","x":"auffangen. Der destillierte Ichor ist nicht komplett rein, aber viel reaktionsfreudiger. Wenn ihn ein Riss berührt, kann er eine Mythos-Reaktion hervorrufen (s. S. 86Schläfer:innen werden temporär vom entsprechenden Mythos berührt.","sz":9.5,"box":[309.0,59.9,538.3,119.4],"p":163,"i":7,"sec":"ichor-destillerie"},{"t":"card","x":"<b>Das Zeug in den Fässern ist der Stoff, aus dem die Legenden sind,</b> und zwar wortwörtlich: Risse sehen darin Visionen des Mythos (als würden sie <b>hinter den Nebel blicken</b>. Um Hinweise zu erhalten, müssen sie jedoch die entsprechende Aktion machen).","sz":null,"k":"yellow","box":[309.3,130.8,541.7,214.6],"p":163,"i":8,"sec":"ichor-destillerie"},{"t":"sh","x":"<b>DER MINENSCHACHT</b>","sz":10.0,"box":[309.4,229.3,425.3,239.3],"p":163,"i":9,"sec":"ichor-destillerie"},{"t":"p","x":"Im Zentrum der Destillerie erhebt sich eine stabile, niedrige Steinmauer, die einen ausgehobenen, von Balken gestützten Schacht umgibt. Darüber befindet sich ein Turm mit Kurbelmechanismus, der mit einer Eisenkette verbunden ist, die man hinablassen kann. Der destillierte Ichor landet so unten in Armands Labor (durch die <u>Aqua-Fortis-Zisterne</u> in die <u>Goldmine).</u>","sz":9.5,"box":[309.0,244.9,541.4,329.4],"p":163,"i":10,"sec":"ichor-destillerie"},{"t":"card","x":"<b>Der Turm, Kessel, der Kurbelmechanismus, die Kette und die Stützbalken im Minenschacht bestehen aus einer Legierung, die normalerweise nur unter Laborbedingungen existiert: die Kombination aus Gold und Eisen</b>. Sie entsteht durch alchemistische Kräfte.","sz":null,"k":"yellow","box":[309.3,346.2,541.7,430.0],"p":163,"i":11,"sec":"ichor-destillerie"},{"t":"card","x":"Die Kettenspule ist riesig: Sie muss mindestens 60 m Kette enthalten.","sz":null,"k":"yellow","box":[309.3,439.2,541.7,472.9],"p":163,"i":12,"sec":"ichor-destillerie"},{"t":"sh","x":"<b>DER STEINBALKON</b>","sz":10.0,"box":[309.4,490.8,413.8,500.8],"p":163,"i":13,"sec":"ichor-destillerie"},{"t":"p","x":"Im hinteren Teil des Raums befindet sich eine Öffnung im Boden. Dort führt eine lange Wendeltreppe in einen Keller. In der hinteren Wand klafft ein grober Tunnel, der in einer natürlichen Höhle endet, von der aus man die <u>Aqua-Fortis-Zisterne</u> sieht: einen riesigen unterirdischen Brunnen, der mit leuchtender weißer Flüssigkeit gefüllt ist. Wenn die Jünger:innen den Kessel herablassen, sieht man, wie er sich dem Strudel in der Mitte nähert.","sz":9.5,"box":[309.0,506.4,540.6,615.9],"p":163,"i":14,"sec":"ichor-destillerie"}],"size":[595.276,841.89]},"164":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 2:","sz":14.0,"box":[53.9,379.4,122.1,393.4],"p":164,"i":0,"skip":true,"sec":"schicht-2-die-zisterne"},{"t":"h","x":"DIE ZISTERNE","sz":23.0,"box":[53.9,401.7,182.4,424.7],"p":164,"i":1,"skip":true},{"t":"h","x":"AQUA-FORTIS-ZISTERNE","sz":16.0,"box":[79.7,438.3,238.7,454.3],"p":164,"i":2,"skip":true,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"Die Höhle ist gewaltig: an ihrer höchsten Stelle 45 m hoch und an der breitesten 150 m lang. Wasserfälle von der Decke füllen sie mit Aqua Fortis. Die Flüssigkeit fließt in der Mitte der Zisterne durch den Schacht in die <u>Goldmine</u> ab, und von dort aus führt Armands Magie es wieder in den Kreislauf zurück. Die Unterbrechung der Recycling-Magie ist schwierig, aber machbar (<i>Bannen 4</i>), hat jedoch wenig Wirkung: Alles in der <u>Goldmine</u> ist resistent gegen Aqua Fortis (und die Goldenen atmen nicht, können also nicht ertrinken), während die vierte Ebene eine versiegelte, separate Höhle ist. Die Flutung der <u>Goldmine</u> mit Aqua Fortis wird eher den SC als Armand schaden.","sz":9.5,"box":[309.0,432.0,539.1,591.5],"p":164,"i":3,"sec":"aqua-fortis-zisterne"},{"t":"ro","x":"Ihr kommt im Dunklen in einem weiten Hohlraum. Das erste, was euch auffällt, ist die Kakophonie des rauschenden Wassers ringsum. Tosende Wasserfälle und tropfende Rinnsale ergießen sich in die endlose Weite, die so groß ist wie das Herrenhaus selbst. Aber die Flüssigkeit ist kein Wasser. Sie scheint schwach zu leuchten, zeichnet Pinselstriche aus trübem Licht über die vielen Säulen und Gewölbebögen, die die Fundamente der Villa stützen, und sammelt sich in einem breiten, weiß leuchtenden Teich. Dann seht ihr im Mittelpunkt einen Strudel. Darunter muss sich etwas befinden.","sz":9.0,"box":[62.4,456.7,283.8,616.9],"p":164,"i":4,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"In der Zisterne unterhalb der Villa findet die <b>zweite Phase des alchemistischen Großen Werks, die Läuterung,</b> statt. Die Zisterne ist gefüllt mit einer silbrig-weiß leuchtenden Flüssigkeit namens <b>Aqua Fortis</b>, die alles schmelzen kann außer Gold und dessen Äquivalent, dem Mythos. Dieser Aqua-Fortis-Teich dient dazu, die letzten „Unreinheiten“ abzuwaschen: sowohl vom destillierten Ichor als auch von jedem, der versucht, Armand zu finden. <b>Wenn Aqua Fortis mit Menschen in Kontakt kommt, löscht es deren Identität aus und hinterlässt den reinen Mythos.</b>","sz":9.5,"box":[53.9,625.9,286.2,760.5],"p":164,"i":5,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"Wenn du den Fall als Raub spielst, kannst du die folgenden Hinweise im Voraus oder in einer Rückblende präsentieren.","sz":9.5,"box":[309.0,600.1,533.3,634.6],"p":164,"i":6,"sec":"aqua-fortis-zisterne"},{"t":"sh","x":"<b>INFORMATIONEN ÜBER DIE ZISTERNE</b>","sz":10.0,"box":[309.4,648.2,518.2,658.2],"p":164,"i":7,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Die Zisterne ist so konzipiert, dass fast nichts in die darunter liegende <u>Goldmine</u> gelangen kann, ohne die Flüssigkeit zu berühren.","sz":null,"k":"yellow","box":[309.3,663.6,541.7,709.9],"p":164,"i":8,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Die Wände sind mit Goldadern durchzogen (die sie immun gegen Aqua Fortis machen).","sz":null,"k":"yellow","box":[309.3,719.1,541.7,752.8],"p":164,"i":9,"sec":"aqua-fortis-zisterne"}],"size":[595.276,841.89]},"165":{"tab":"","blocks":[{"t":"card","x":"<b>Der Teich hat keine Ufer, an denen man stehen könnte.</b> Die zerklüfteten Wände steigen beinahe senkrecht von der Oberfläche auf und verschmelzen mit den Fundamenten des Hauses, um darüber zu hohen Gewölben zu werden.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,138.0],"p":165,"i":0,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Die Flüssigkeit fällt in Wasserfällen von spitzen Vorsprüngen in der Kuppeldecke herab und fließt aus dem Becken an den Wänden entlang wieder nach oben, offensichtlich durch Magie. <b>Wer fliegen oder klettern kann, könnte beim Durchqueren trotzdem nass werden.</b>","sz":null,"k":"yellow","box":[54.1,147.2,286.6,231.0],"p":165,"i":1,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Der Strudel in der Mitte des Teichs mündet in einen weiteren Schacht, die Fortsetzung des Schachts in der <u>Ichor-Destillerie.</u> <b>Er ist die einzige physische Öffnung zur darunter liegenden <u>Goldmine.</u></b> Wer ohne Schutz durch den Strudel hinuntersteigt, wird durchnässt.","sz":null,"k":"yellow","box":[54.1,240.2,286.6,324.0],"p":165,"i":2,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Magieanwender:innen können feststellen, dass die <u>Goldmine</u> unten mit <t>Schutzzeichen 5</t> gegen magische Transporte geschützt ist, <b>was jede magische Abkürzung schwer macht.</b>","sz":null,"k":"yellow","box":[54.1,333.2,286.6,392.0],"p":165,"i":3,"sec":"aqua-fortis-zisterne"},{"t":"sh","x":"<b>ANALYSE DER FLÜSSIGKEIT</b>","sz":10.0,"box":[54.3,400.1,205.7,410.1],"p":165,"i":4,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Die Flüssigkeit ist eine magische Säure, <b>Aqua Fortis, die alles außer Gold auflösen kann</b>.","sz":null,"k":"yellow","box":[54.1,412.7,286.6,446.7],"p":165,"i":5,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"In der mystischen Bedeutung der alchemistischen Sprache bedeutet „alles außer Gold auflösen“, <b>dass diese Säure alles schmilzt, was nicht zum Mythos gehört</b>.","sz":null,"k":"yellow","box":[54.1,455.6,286.6,514.7],"p":165,"i":6,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Jeder, der sich in alchemistischen Überlieferungen auskennt (s. S. <i>Der Kult des Gottkönigs</i>, S. 130), kann einen Zusammenhang mit der <b>Weißungs- oder Läuterungsstufe des alchemistischen Großen Werkes herstellen</b>.","sz":null,"k":"yellow","box":[54.1,523.9,286.6,595.0],"p":165,"i":7,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Als magische Substanz wirkt Aqua Fortis auch auf entmaterialisierte oder flüssige Wesen, <b>kurz, auf alles, was die Flüssigkeit berührt oder durch sie hindurchgeht.</b>","sz":null,"k":"yellow","box":[54.1,604.2,286.6,663.0],"p":165,"i":8,"sec":"aqua-fortis-zisterne"},{"t":"sh","x":"<b>SUCHE NACH MÖGLICHKEITEN, IN DIE ZISTERNE ZU GELANGEN</b>","sz":10.0,"box":[54.3,672.9,263.4,694.9],"p":165,"i":9,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Der offensichtliche Weg führt <b>durch den Minenschacht</b> in der <u>Ichor-Destillerie,</u> entweder durch einen Sprung oder einen Sturz oder indem man sich in einem Kessel hinablässt. <b>Auf diesem Weg ist man der Flüssigkeit am meisten ausgesetzt.</b>","sz":null,"k":"yellow","box":[54.1,700.4,286.6,784.2],"p":165,"i":10,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Wenn man die Wendeltreppe auf der Rückseite der <u>Ichor-Destillerie</u> hinuntersteigt, gelangt man auf einen steinernen Balkon, von dem aus man die Zisterne überblickt. <b>So kann man trockenen Fußes die Zisterne betreten,</b> aber das löst nicht das Problem, wo man innen stehen soll, oder wie man durch den Strudel kommt.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,150.6],"p":165,"i":11,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Wenn man die Zisterne vom Balkon aus betrachtet, <b>sieht man eine kleinere Höhle, die sich in die Zisterne hinein erstreckt</b> (eine Höhle in der Höhle) und Schutz vor den Wasserfällen entlang der Wand bietet. <b>Mit einem weiteren Eingang dort könnte man einsteigen, ohne nass zu werden.</b> Aber das löst nicht das Problem, wo man stehen soll, oder wie man durch den Strudel kommt.","sz":null,"k":"yellow","box":[309.3,159.6,541.7,281.1],"p":165,"i":12,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"<b>Die geheime Wendeltreppe in der Bibliothek des <u>verlassenen Hauses</u> führt in die kleinere Höhle.</b> Im Inneren befindet sich ein Kiesufer, an dem eine <b>goldene Gondel</b> liegt. Die kleinere Höhle ist mit Aqua Fortis geflutet, der Höhleneingang jedoch hoch genug, dass das Boot hindurchfahren und unter Umgehung der Wasserfälle in die Zisterne gelangen kann.","sz":null,"k":"yellow","box":[309.3,290.0,541.7,398.9],"p":165,"i":13,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"<b>Ein Schiff aus Gold würde in Aqua Fortis sinken</b>, es sei denn, jemand mit Kenntnis der Transmutation von Gold (wie die Goldenen aus der <u>Goldmine</u> unten) hindert oder steuert es.","sz":null,"k":"yellow","box":[309.3,408.1,541.7,466.8],"p":165,"i":14,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Der Versuch, <b>einen Tunnel durch die Erde</b> zu graben, könnte die alchemistischen Schutzvorrichtungen auslösen und den Tunnel fluten, wenn sich der Zugang unter der Oberfläche befindet.","sz":null,"k":"yellow","box":[309.3,476.1,541.7,547.5],"p":165,"i":15,"sec":"aqua-fortis-zisterne"},{"t":"sh","x":"<b>DIE ARBEIT DER JÜNGER:INNEN VERFOLGEN</b>","sz":10.0,"box":[309.4,558.8,484.1,580.8],"p":165,"i":16,"sec":"aqua-fortis-zisterne"},{"t":"card","x":"Jünger:innen Armands lassen destillierten Ichor in einem Kessel aus einer magischen Gold-Eisen-Legierung (resistent gegen Aqua Fortis) an einer Kette durch den Minenschacht in der <u>Ichor-Destillerie</u> herab. Wenn der Kessel in den Strudel taucht, <b>füllt er sich mit Aqua Fortis, was die letzten Unreinheiten im Ichor auflöst</b>. Als 100 % reine Mythos-Essenz kommt er in der darunter liegenden Kammer (der <u>Goldmine)</u> an. <b>Jemand sammelt ihn dort ein</b> und zieht an der Kette, um zu signalisieren, den Kessel wieder nach oben zu ziehen.","sz":null,"k":"yellow","box":[309.3,584.4,541.7,743.0],"p":165,"i":17,"sec":"aqua-fortis-zisterne"}],"size":[595.276,841.89]},"166":{"tab":"","blocks":[{"t":"sh","x":"<b>KONTAKT MIT AQUA FORTIS</b>","sz":10.0,"box":[54.3,62.8,209.9,72.8],"p":166,"i":0,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"<b>Die Zisterne bietet viele Möglichkeiten, mit Aqua Fortis in Berührung zu kommen.</b> Der Strudel ist am schwierigsten zu durchqueren: Wenn ein SC nicht in Gold gehüllt ist oder das Aqua Fortis verdrängen kann, würde er nass werden.","sz":9.5,"box":[53.9,78.5,283.8,137.8],"p":166,"i":1,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"<b>Für Menschen bedeutet der Kontakt mit Aqua Fortis eine Auflösung ihrer Identität.</b> Emotionale Bindungen, Glaube, Überzeugungen – all das, was den Logos eines Charakters ausmacht – schmilzt bei Kontakt mit dieser mystischen Säure.","sz":9.5,"box":[53.9,146.6,280.5,206.0],"p":166,"i":2,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"Berührt jemand die Flüssigkeit, spürt er, wie sich sein Geist und Herz leeren und läutern. Dies ist weder gut noch schlecht, angenehm oder unangenehm – es geschieht einfach. Die betroffene Person begreift intuitiv, dass sie sich und alles, was ihr wichtig ist, verlieren wird, wenn sie den Kontakt nicht sofort beendet.","sz":9.5,"box":[53.9,214.7,286.3,286.7],"p":166,"i":3,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"Personen, die unfreiwillig mit Aqua Fortis in Berührung kommen, erhalten den Zustand <t>bespritzt</t> oder <t>durchnässt</t>, wobei die Stufe vom Ausmaß des Kontakts abhängt: 1 für ein paar Tropfen, 2 für einen Spritzer und so weiter. Wenn man ohne Schutz durch den Strudel geht, erhält man den Zustand <t>durchnässt 5</t>, während das Eintauchen in Aqua Fortis ohne Schutz den Zustand <t>durchnässt 6</t> verursacht. Die SC können <b>Sich der Gefahr stellen</b>, indem sie Stärken für Schutz (alchemistisch, magisch, golden usw.) oder Entschlossenheit und Willenskraft einsetzen. Selbst wenn jemand eine Lösung findet, sollte die Person <b>Sich der Gefahr stellen</b>, da sie wahrscheinlich nicht völlig wasserabweisend ist. S. auch Textkasten <b>Verteidigung mit Momentum</b>. Wende die folgende Spezialaktion an:","sz":9.5,"box":[53.9,295.3,284.5,480.0],"p":166,"i":4,"sec":"aqua-fortis-zisterne"},{"t":"h","x":"VERTEIDIGUNG MIT MOMENTUM","sz":14.0,"box":[320.3,61.0,474.1,75.0],"p":166,"i":5,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"<b>Sich der Gefahr stellen</b> ist eine letzte Verteidigung, da man dafür den Zustand erhalten muss, um ihn dann zu reduzieren oder vollständig zu vermeiden. Die Aktion wird erst gewürfelt, wenn der SC den Zustand erhält.","sz":9.0,"box":[320.3,87.5,522.4,144.5],"p":166,"i":6,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"Erinnere die Spieler:innen daran, dass sie mit <b>Das Blatt wenden</b> im Voraus Momentum erzeugen und später ausgeben können, um Zustände um 1 pro Punkt Momentum zu verringern. Dies ist eine Form des Schutzes, die es ermöglicht, im Voraus zu wissen, wie viel die Verteidigung aushält. Bei 10+ können die Spieler:innen sogar 1 Momentum ausgeben, um den Schutz auf andere auszudehnen, indem sie pro Punkt Momentum 1 Stufe von allen Zustandswerten, die die Gruppe erleidet, entfernen.","sz":9.0,"box":[320.3,153.2,523.3,270.2],"p":166,"i":7,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"Momentum hat Grenzen. Man kann es zusätzlich zu <b>Sich der Gefahr stellen</b> verwenden, aber die beim Erschaffen verwendeten Stärken können nicht wiederverwendet werden, wenn es sich um denselben Zustand handelt. Denk daran, dass SC nicht mehrere Chargen Momentum für denselben Zweck anlegen können. Stattdessen können sie eine bestehende Charge durch eine neue ersetzen.","sz":9.0,"box":[320.3,278.8,521.0,371.8],"p":166,"i":8,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"<b>Das Ich abwaschen</b>: Nachdem der SC <b>Sich der Gefahr gestellt</b> und alle potenziellen Verteidigungsmaßnahmen angewandt hat, markiert er für jede Stufe des Aqua-Fortis-Zustands, den er erhalten hat, 1 Bruch auf einem beliebigen Logos-Thema (nach Wahl der Spieler:in).","sz":9.5,"box":[62.4,491.3,285.7,563.3],"p":166,"i":9,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"Sobald die Natur des Wassers klar ist, verstößt die Entscheidung, es zu berühren, gegen jede Identität. SC können so viel Bruch markieren, wie sie wollen. Es könnte eine Szene werden, in der ein SC beschließt, ein Logos-Thema ganz oder teilweise wegzuwaschen.","sz":9.5,"box":[53.9,574.9,279.4,634.4],"p":166,"i":10,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"<b>Verwende die Begegnung mit dieser teuflischen Säure cineastisch:</b>","sz":9.5,"box":[53.9,643.1,269.5,665.1],"p":166,"i":11,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"• Frag, wie sich die Charaktere fühlen, nachdem sie erkannt haben, dass die Suche nach ewigen Leben nichts für schwache Nerven ist und Opfer fordert.","sz":9.5,"box":[53.9,676.5,272.3,711.0],"p":166,"i":12,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"• Spiel die Ersetzung von Logos-Themen aus, indem das Aqua Fortis die Dinge, die den SC am Herzen liegen, wegspült.","sz":9.5,"box":[53.9,719.7,274.7,754.2],"p":166,"i":13,"sec":"aqua-fortis-zisterne"},{"t":"p","x":"• Beschreibe die Klarheit des Geistes, die auf diese ultimative Läuterung folgt, die Sonne des Mythos des Charakters, die vom Privatleben nicht mehr behindert wird. Wenn die Spieler:in ein neu entstehendes Mythos-Thema gewählt hat, lass die Kräfte sichtbar werden. Wenn jemand die Schwelle zum Avatar überschritten hat, lass den SC einen großen Auftritt haben, bei dem er die ganze Höhle mit seiner Macht erleuchtet.","sz":9.5,"box":[309.0,409.3,536.8,518.8],"p":166,"i":14,"sec":"aqua-fortis-zisterne"}],"size":[595.276,841.89]},"167":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 3:","sz":14.0,"box":[53.9,61.9,122.0,75.9],"p":167,"i":0,"skip":true,"sec":"schicht-3-narrengold"},{"t":"h","x":"NARRENGOLD","sz":23.0,"box":[53.9,84.2,183.6,107.2],"p":167,"i":1,"skip":true},{"t":"p","x":"Die Goldmine ist der Ort, an dem die Mythos-Essenz landet, nachdem sie die ersten beiden Stufen des Magnum Opus durchlaufen hat: Fäulnis und Läuterung. Wer es bis hierher geschafft hat, den hat das Aqua Fortis wohl teilweise von seiner persönlichen Identität gereinigt. Wenn diese Personen diese Ebene des Komplexes erreichen, erwachen sie. Alles ist so gebaut, dass es <b>die dritte Stufe, das Erwachen</b>, und die Lagerung von Mythos-Essenzen unterstützt.","sz":13.0,"box":[53.9,115.1,285.2,287.6],"p":167,"i":2,"sec":"schicht-3-narrengold"},{"t":"card","x":"GOLDMINE","sz":null,"k":"yellow","box":[41.8,297.8,178.0,322.3],"p":167,"i":3,"sec":"schicht-3-narrengold"},{"t":"ro","x":"Als ihr den Strudel durchquert, reißt euch der Strom aus silbrig-weißer Flüssigkeit in einen Schacht, bis sie unerwartet von euch abfließt und an den Wänden versickert. Trocken steigt ihr weiter in die Dunkelheit hinab und landet auf einem vergoldeten Gitter. Ihr befindet euch in einem seltsamen Tunnel: Decke und Wände erinnern an ein Bergwerk, aber der Boden ist aus purem Gold und mit alchemistischen Symbolen verziert. Drei vermummte Gestalten stehen in einem Dreieck um das Gitter herum und starren euch mit leerem Blick an. Im schwachen Licht der Laterne spiegelt sich ihre Haut, und man kann erkennen, dass auch sie golden ist.","sz":9.0,"box":[62.4,324.5,283.8,495.5],"p":167,"i":4,"sec":"schicht-3-narrengold"},{"t":"p","x":"Die Goldmine ist ein vertikaler Schacht, der mit einem horizontalen Tunnel direkt unter der <u>Ichor-Destillerie</u> und dem Strudel der <u>Aqua-Fortis-Zisterne</u> verbunden ist. Das Aqua Fortis aus der Zisterne fließt den Schacht hinunter, bis die Wände in der Mitte es auf magische Weise in Kanäle und zurück in die Zisterne leiten. Der Schacht führt weiter hinunter zum Tunnel, wo er sich über einem goldenen Gitter öffnet, auf dem der Kessel mit veredeltem Ichor aus der Destillerie landet. Der Stollen führt von hier bis zum <u>Essenz-Gewölbe.</u>","sz":9.5,"box":[53.9,504.5,284.6,626.5],"p":167,"i":5,"sec":"schicht-3-narrengold"},{"t":"h","x":"DIE KASSE KLINGELT!","sz":14.0,"box":[65.2,649.9,166.0,663.9],"p":167,"i":6,"sec":"schicht-3-narrengold"},{"t":"p","x":"Diese Ebene von Armands Komplex ist buchstäblich übersät mit Gold, Transmutationen und Tinkturen, die Gold direkt aus den Adern der Erde saugen können. Das Team könnte hier ein Vermögen machen. Wenn der Raub das Ziel ist und das Team es schafft, solltest du in Erwägung ziehen, ihm Besitztümer als zusätzliches Thema zu geben, um den gefundenen Reichtum abzubilden.","sz":9.0,"box":[65.2,676.4,273.8,769.4],"p":167,"i":7,"sec":"schicht-3-narrengold"},{"t":"p","x":"In der Mine wohnen die <b>Goldenen</b>, drei von Jünger:innen Armands, deren Körper er mit Gold erfüllt und so in magische Automaten verwandelt hat. Die Goldenen sind androgyne Wesen, die in einfache gelbe Wollgewänder gekleidet sind. Sie beherrschen die Transmutation des Goldes, mit der sie nicht nur Gold manipulieren, sondern auch Mythos-Essenzen (die allegorische Entsprechung von „Gold“) transportieren können. Sie sind die Hüter:innen von Armands Schatzkammer der Mythos-Essenzen und Tinkturen und dienen ihm seit Jahrzehnten. Sie alle waren einst Jünger:innen, die es wagten, das Aqua Fortis zu durchqueren und dabei ihr Selbst völlig verloren. Nun dienen sie als harsche Demonstration von Armands Geiz und seiner Weigerung, die Macht zu teilen.","sz":9.5,"box":[309.0,62.5,540.4,247.0],"p":167,"i":8,"sec":"schicht-3-narrengold"},{"t":"card","x":"In diesem Stollen scheint der Weg zu enden: Keine Öffnungen oder verborgenen Türen führen weiter. Wenn es jemanden oder etwas in der Tiefe gibt, muss er unter Tonnen von Felsen begraben sein.","sz":null,"k":"yellow","box":[309.3,257.5,541.7,328.9],"p":167,"i":9,"sec":"schicht-3-narrengold"},{"t":"card","x":"Wer sich in der alchemistischen Überlieferung auskennt (s. S. <i>Der Kult des Gottkönigs</i>, S. 130), kann das Bergwerk mit der Gilbungs- oder <b>Erwachens-Stufe des Großen Werkes</b> in Verbindung bringen. Hier wird deutlich, dass der gesamte Komplex als alchemistisches Experiment konzipiert ist und es <b>daher eine vierte Stufe, die Transformation, geben muss und wahrscheinlich auf den Mythos einwirkt.</b>","sz":null,"k":"yellow","box":[309.3,338.1,541.7,459.4],"p":167,"i":10,"sec":"schicht-3-narrengold"},{"t":"sh","x":"<b>BEOBACHTUNG DER GOLDENEN</b>","sz":10.0,"box":[309.4,475.2,483.0,485.2],"p":167,"i":11,"sec":"schicht-3-narrengold"},{"t":"card","x":"Die Goldenen sind in Gold mumifizierte Menschen. Sie haben keine Persönlichkeit. Wahrscheinlich waren sie Jünger:innen, die dem Aqua Fortis trotzten und ihre Identität verloren. <b>Anders als die oberen Jünger:innen kennen sie die Transmutation des Goldes.</b>","sz":null,"k":"yellow","box":[309.3,490.8,541.7,574.6],"p":167,"i":12,"sec":"schicht-3-narrengold"},{"t":"card","x":"<b>Die Goldenen sind nichts weiter als ferngesteuerte Gabelstapler</b>: Ihre Aufgabe ist es, den Ichor aus dem Kessel zu holen und im <u>Essenz- Gewölbe</u> zu lagern, bis jemand danach verlangt (Armand für seine Forschung). Dann holen sie die Essenz und schicken sie durch die Erde, <b>wobei sie die Goldadern schmelzen und wie ein Rohrpostsystem benutzen.</b>","sz":null,"k":"yellow","box":[309.3,583.8,541.7,692.6],"p":167,"i":13,"sec":"schicht-3-narrengold"},{"t":"card","x":"<b>Die Goldenen und ihr Meister kommunizieren, indem sie die Goldadern manipulieren</b>: Sie bringen sie zum Schwingen, um Töne zu erzeugen, oder lassen Worte und Symbole erscheinen. <b>Ihr Meister ist irgendwo darunter.</b>","sz":null,"k":"yellow","box":[309.3,701.6,541.7,773.0],"p":167,"i":14,"sec":"schicht-3-narrengold"}],"size":[595.276,841.89]},"168":{"tab":"","blocks":[{"t":"card","x":"<b>Die Goldenen reagieren nur auf Befehle, die in Gold geschrieben oder ertönt sind, behandeln aber alle Befehle gleich</b>, unabhängig von ihrer Quelle. Bei Konflikten reagieren sie auf den zuletzt erteilten Befehl.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,125.6],"p":168,"i":0,"sec":"schicht-3-narrengold"},{"t":"sh","x":"<b>AUF DER SUCHE NACH EINEM WEG IN DIE UNTERE EBENE</b>","sz":10.0,"box":[54.3,142.8,281.4,164.8],"p":168,"i":1,"sec":"schicht-3-narrengold"},{"t":"card","x":"<b>Der offensichtliche Weg ist ein Tunnel durch die Erde</b>, aber dieser Teil des Komplexes ist durch starke Schutzwälle geschützt (<t>Schutzzeichen 5</t>, <t>Schutzzeichen 6</t> gegen Teleportation).","sz":null,"k":"yellow","box":[54.1,171.9,286.6,243.1],"p":168,"i":2,"sec":"schicht-3-narrengold"},{"t":"card","x":"Durch Deduktion oder magische Entdeckung kann man herausfinden, dass <b>die Goldadern nicht gegen legendäre Mächte geschützt</b> sind (das können sie auch nicht, da sie zum Transport von Mythos-Essenz verwendet werden). <b>Jeder, der in eine Essenzflasche passt, könnte von den Goldenen oder von jemandem mit Macht über Gold, dadurch geschickt werden.</b>","sz":null,"k":"yellow","box":[54.1,252.3,286.6,361.2],"p":168,"i":3,"sec":"schicht-3-narrengold"},{"t":"threat","stars":"★","name":"GOLDENE","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / GEIST BEEINFLUSSEN –","items":["Sich an ihren Befehl, die Mine zu bewachen, erinnern und die Goldadern nutzen, um Armand auf die Anwesenheit des Teams aufmerksam zu machen (<b>Die Dinge richtig kompliziert machen</b>)","Auf Armands Befehl den Goldboden unter den Füßen einer Person verflüssigen und ihn dann verfestigen (<t>kann nicht gehen 3</t>)","Telekinetische Manipulation einer Essenz, die jemand stehlen will, um sie in <u>Armands Labor</u> zu senden (<b>Ihnen etwas verweigern, das sie wollen</b>)","Dastehen und Staub sammeln, bis ein Befehl sie zum Leben erweckt"],"box":[365.6,57.5,375.8,69.5],"p":168,"i":4,"sec":"schicht-3-narrengold"},{"t":"h","x":"ESSENZ-GEWÖLBE","sz":16.0,"box":[334.8,307.6,454.6,323.6],"p":168,"i":5,"skip":true,"sec":"essenz-gewoelbe"},{"t":"ro","x":"Beim Anblick des Goldes fällt euch die Kinnlade herunter. Die Wände dieses grob behauenen Raums sind von oben bis unten mit Schränken aus Goldguss bedeckt, Reihen um Reihen kleiner Fächer mit Kristallscheiben, und in jedem ein runder Kristallkolben, in dem Visionen von Wundern aufblitzen und der vor Kraft knistert: eine Legende in der Flasche. Wie viele Menschen hat der Alchemist ihres Funkens beraubt, um diesen Raum zu füllen? Weiß er, wie viele er gehortet hat, und wie viele er überhaupt braucht?","sz":9.0,"box":[317.5,325.9,533.5,464.5],"p":168,"i":6,"sec":"essenz-gewoelbe"},{"t":"p","x":"Hier lagert raffinierter und gereinigter Ichor – also reine Mythos-Essenz –, bis Armand ihn für die Forschung benötigt. Armand hat die Kammer gebaut, um viele Mythos-Essenzen nebeneinander aufzubewahren. Die Tatsache, dass jede dieser Essenzen von einem Menschen stammt, der nun keine Seele mehr hat, ist ein weiteres Zeugnis von Armands Gier. Der Raum ist gesäumt von goldenen Schränken mit Hunderten von Fächern, die je eine Essenz enthalten. Sie sind in kugelförmigen Fläschchen eingeschlossen, von denen jedes in einer Vertiefung ruht. Bei dieser Verfeinerung kann jeder die legendären Szenen sehen und hören, die gespeichert sind – sogar Schläfer:innen (auch wenn sie sich später vielleicht nicht mehr daran erinnern).","sz":9.5,"box":[309.0,473.5,541.8,645.5],"p":168,"i":7,"sec":"essenz-gewoelbe"}],"size":[595.276,841.89]},"169":{"tab":"","blocks":[{"t":"h","x":"OPTIONALE HERAUSFORDERUNG: DIE TRESORTÜR","sz":13.0,"box":[65.2,61.7,272.4,74.7],"p":169,"i":0,"sec":"essenz-gewoelbe"},{"t":"p","x":"Wenn du willst, versperrt eine Tresortür das Ende des Tunnels zum Essenz-Gewölbe. Sie ist äußerst stabil (<i>Durchbohren 5</i> und <i>Einschlagen 6</i>), und das Knacken der alchemistischen Schlösser erfordert einen begabten Tresorknacker oder Magier (<i>Knacken 4</i>; <i>Knacken 3</i>, wenn man sie aufbohrt). Die Goldenen können den Tresor mit der Transmutation des Goldes aufschließen, aber sie ignorieren entsprechende Befehle und öffnen sie nur, wenn sie eine Essenz bringen sollen. Ein Einschlagen der Tür oder ein Fehlwurf bei der Herausforderung kann Armand auf die Anwesenheit des Teams aufmerksam machen. Ein Fehlwurf kann dazu führen, dass jemand mit den Essenzen darin festsitzt oder <t>Lockdown 5</t> für den Tresor auslösen.","sz":9.0,"box":[65.2,87.5,266.7,264.5],"p":169,"i":1,"sec":"essenz-gewoelbe"},{"t":"p","x":"Dieser Raum verkörpert die Bedrohungen der Phase des Erwachens des Magnum Opus: Das <b>Narrengold</b>. Wenn man die Essenz oder das Individuum nicht in der vierten Phase stabilisiert (als funktionale Tinktur), ist sie wertlos, weil sie leicht mit anderen interagieren, verunreinigt werden oder sich verflüchtigen.","sz":9.5,"box":[53.9,289.0,285.9,361.0],"p":169,"i":2,"sec":"essenz-gewoelbe"},{"t":"p","x":"<b>Die Bedrohung im Essenz-Gewölbe liegt in den äußerst flüchtigen Mythos-Essenzen, die mit allem, was sie berühren, in Wechselwirkung treten.</b> Solange sie sich in den goldenen Schränken befinden, sind sie inaktiv. Das Öffnen eines Fachs, ohne die Essenz zu kontrollieren, kann zu einer Mythos-Explosion führen. Die Goldenen kontrollieren die Essenzen mit Hilfe der Transmutation des Goldes. Andere Magieanwender:innen können dies mit entsprechender Magie tun.","sz":9.5,"box":[53.9,369.8,286.0,479.1],"p":169,"i":3,"sec":"essenz-gewoelbe"},{"t":"sh","x":"<b>WELCHE MYTHOS-ESSENZEN GIBT ES HIER?</b>","sz":10.0,"box":[54.3,491.9,258.9,514.7],"p":169,"i":4,"sec":"essenz-gewoelbe"},{"t":"p","x":"Die Auswahl der Mythen, die hier lagern, bleibt weitgehend dir überlassen. Hier sind einige Vorschläge für nützliche Quellen:","sz":9.5,"box":[53.9,520.3,280.6,554.8],"p":169,"i":5,"sec":"essenz-gewoelbe"},{"t":"p","x":"• Zum schnellen Nachschlagen kann die <b>Liste der Mythen</b> in diesem Buch dienen","sz":9.5,"box":[53.9,566.3,266.2,588.4],"p":169,"i":6,"sec":"essenz-gewoelbe"},{"t":"p","x":"• Du kannst deine Spieler:innen bitten, Mythen vorzuschlagen, und dann ihre Vorschläge auf deine Bedürfnisse abstimmen","sz":9.5,"box":[53.9,597.0,275.2,631.5],"p":169,"i":7,"sec":"essenz-gewoelbe"},{"t":"p","x":"• Durchsuche die Wikipedia-Artikel mit <b>Listen der Götter und Sagengestalten der diversen Kulturkreise, Märchen oder moderne Sagen.</b>","sz":9.5,"box":[53.9,640.2,277.8,674.8],"p":169,"i":8,"sec":"essenz-gewoelbe"},{"t":"p","x":"Wenn du Mythen für diese Szene auswählst, bedenke:","sz":9.5,"box":[53.9,686.2,279.6,695.7],"p":169,"i":9,"sec":"essenz-gewoelbe"},{"t":"p","x":"• Du solltest die Mythen der Opfer von Armands Operation, deren Tinktur man nie gefunden hat, wie z. B. die Opfer des Magnum-Opus-Kults in <i>Der Kult des Gottkönigs,</i> mit aufnehmen.","sz":9.5,"box":[53.9,707.2,282.9,754.2],"p":169,"i":10,"sec":"essenz-gewoelbe"},{"t":"p","x":"• Ausgenommen sind Essenzen, die Armand hat, wie Will Harris, deren Mythos er zu einer Tinktur verarbeitet hat, oder Juan Delamar, dessen Essenz für das Lebenselixier in Schicht 4 nötig ist (aus <i>Athanor</i>).","sz":9.5,"box":[309.0,59.9,541.3,106.9],"p":169,"i":11,"sec":"essenz-gewoelbe"},{"t":"p","x":"• Du solltest die Mythen etablierter NSC in deiner Kampagne ausschließen, wenn bekannt ist, dass sie nicht zu Armands Opfern gehören, insbesondere aus dieser Staffel: den Fischerkönig (Corbin Payne), die Schneekönigin (Krystal Knight), König Artus (Vince Beaumont) und Parzival (Rio Beaumont).","sz":9.5,"box":[309.0,115.6,538.7,187.6],"p":169,"i":12,"sec":"essenz-gewoelbe"},{"t":"sh","x":"<b>DURCHSUCHUNG DER SCHATZKAMMER</b>","sz":10.0,"box":[309.4,201.2,524.9,211.2],"p":169,"i":13,"sec":"essenz-gewoelbe"},{"t":"p","x":"Die SC können Hinweise erhalten, wenn sie <b>hinter den Nebel blicken</b> oder mit nützlichen Stärken (arkanes oder legendäres Wissen) <b>Nachforschungen</b> anstellen. Die Identifizierung des Mythos in einem Fach kostet 1 Hinweis, das Finden eines bestimmten Mythos kostet ebenfalls 1 Hinweis, kann aber länger dauern.","sz":9.5,"box":[309.0,216.8,540.7,288.8],"p":169,"i":14,"sec":"essenz-gewoelbe"},{"t":"sh","x":"<b>INTERAKTION MIT ESSENZEN</b>","sz":10.0,"box":[309.4,302.4,472.8,312.4],"p":169,"i":15,"sec":"essenz-gewoelbe"},{"t":"p","x":"Wenn ein Riss in die Nähe einer reinen Mythos-Essenz kommt, interagieren ihre Mythen. Das kann alles Mögliche zur Folge haben: Schmerzen, eine Explosion, plötzliche Ermächtigung usw.","sz":9.5,"box":[309.0,317.9,539.3,364.9],"p":169,"i":16,"sec":"essenz-gewoelbe"},{"t":"p","x":"Um die Interaktion zu definieren:","sz":9.5,"box":[309.0,373.6,449.9,383.1],"p":169,"i":17,"sec":"essenz-gewoelbe"},{"t":"p","x":"1. <b>Reduziere jeden Mythos auf ein Wort</b> (diese Kurzfassung muss nicht exakt sein). Beispiel: Die böse Königin aus Schneewittchen = EIFERSUCHT, Dornröschen = SCHÖNHEIT.","sz":9.5,"box":[309.0,391.8,529.3,438.8],"p":169,"i":18,"sec":"essenz-gewoelbe"},{"t":"p","x":"2. <b>Bestimme, wie diese Begriffe zusammenwirken</b>. <i>Eifersucht</i> wird <i>Schönheit</i> verzehren wollen.","sz":9.5,"box":[309.0,447.5,536.4,469.5],"p":169,"i":19,"sec":"essenz-gewoelbe"},{"t":"p","x":"3. <b>Führe eine harte Aktion (als Einmischung) aus, die diese Interaktion widerspiegelt</b>. Wenn der SC zum Beispiel der Riss Dornröschen ist, der die Essenz von Schneewittchens böser Königin in der Hand hat, erleidet er <t>verschlungen 4</t>, da die Mythos- Essenz der bösen Königin sein Fleisch zerfetzt.","sz":9.5,"box":[309.0,478.1,536.9,550.1],"p":169,"i":20,"sec":"essenz-gewoelbe"},{"t":"p","x":"Der sichere Weg, die Essenzen zu manipulieren, besteht darin, ihnen die Stärke <i>Stabil</i> zu verleihen, indem man Magie (<b>Das Blatt wenden</b>) oder die Transmutation von Gold einsetzt (durch die Kontrolle der Goldenen oder indem man Gold bewegt, s. u.)","sz":9.5,"box":[309.0,558.8,540.1,618.3],"p":169,"i":21,"sec":"essenz-gewoelbe"},{"t":"sh","x":"<b>ARMANDS LAPSUS</b>","sz":10.0,"box":[309.4,631.9,410.9,641.9],"p":169,"i":22,"sec":"essenz-gewoelbe"},{"t":"p","x":"Auf seiner Suche verlor Armand den Überblick darüber, welche Mythos-Essenzen er gesammelt hatte. Eine der Essenzen, die er vor langer Zeit erhielt, könnte zum Verhängnis werden: die Mythos-Essenz <b>El Dorados</b>, des mythischen goldenen Königs, der sich später zur goldenen Stadt entwickelte. El Dorado hat Macht über Gold (und Städte), so dass jeder, der die Essenz kontrolliert, Gold und Mythos-Essenzen ebenso geschickt manipulieren kann wie die Goldenen.","sz":9.5,"box":[309.0,647.5,541.5,757.0],"p":169,"i":23,"sec":"essenz-gewoelbe"}],"size":[595.276,841.89]},"170":{"tab":"","blocks":[{"t":"card","x":"NEUE HARTE AKTION: NEUES THEMA Bei extremer Übereinstimmung zwischen dem Mythos und dem Riss eines anderen Mythos kann die fremde Essenz diesen Riss temporär als Wirt benutzen. Für SC gilt dies vor allem dann, wenn der interagierende SC ein fehlendes Thema hat (nach dem Ersetzen, aber vor der Wahl eines neuen), wenn er ein neu entstehendes Thema hat oder eine Schläfer:in ist. Je nach Spielstil kann es den Mythos des Charakters ersetzen oder ergänzen. In unserer Version von <i>City of Mist</i> ist jedes Individuum sein Mythos, so dass eine weitere Essenz nur vorübergehend und in selten symbiotisch, sozusagen per Anhalter, mitreisen kann. Gib dem SC ein neues Mythos-Thema und ersetze bei Bedarf ein bestehendes damit. Lass die Spieler:in die Stärken wählen (im Rahmen des Themas). Erstelle das Thema normal mit einem Themenbuch aus dem <i>Spieler:innen- Handbuch</i>. Die Spieler:in kann später erzählerische Aktionen durchführen oder <b>Jetzt reicht’s!</b> einsetzen, um den fremden Mythos loszuwerden und das Thema zu ersetzen.","sz":null,"k":"yellow","box":[55.0,54.1,288.9,407.2],"p":170,"i":0,"sec":"essenz-gewoelbe"},{"t":"sh","x":"<b>DIE ESSENZ EL DORADOS</b>","sz":12.0,"box":[65.2,443.2,219.2,455.2],"p":170,"i":1,"sec":"essenz-gewoelbe"},{"t":"p","x":"<i>Relikt</i>","sz":10.0,"box":[65.2,464.9,91.2,474.9],"p":170,"i":2,"sec":"essenz-gewoelbe"},{"t":"h","x":"MYSTERIUM","sz":10.0,"box":[65.2,486.4,120.5,496.4],"p":170,"i":3,"sec":"essenz-gewoelbe"},{"t":"p","x":"<i>Was verbindet einen König und seine Stadt?</i>","sz":9.0,"box":[65.2,501.1,236.1,510.1],"p":170,"i":4,"sec":"essenz-gewoelbe"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[65.2,521.9,105.8,531.9],"p":170,"i":5,"sec":"essenz-gewoelbe"},{"t":"card","x":"<b><i>Herrschaft über Gold</i></b>, <i>Sich in Gold hüllen</i>, <i>Reichtümer materialisieren</i>, <i>In Gold hüllen</i>, <i>Trends der Stadt beeinflussen</i>, <i>An jeden Ort der Stadt blicken</i>, <i>Gierige ins Verderben locken</i>, <i>Kostbare Erze aufspüren</i>, <i>In Gold verwandeln</i>, <i>Ich bin die Stadt</i>","sz":null,"k":"yellow","box":[65.4,535.4,275.6,593.6],"p":170,"i":6,"sec":"essenz-gewoelbe"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[65.2,605.4,122.1,615.4],"p":170,"i":7,"sec":"essenz-gewoelbe"},{"t":"card","x":"<i>Gold ist weich</i>, <i>Weckt Gier</i>, <i>Fremde Eindringlinge</i>, <i>Sieht sich als Gott</i>","sz":null,"k":"yellow","box":[65.4,618.9,253.7,641.1],"p":170,"i":8,"sec":"essenz-gewoelbe"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[65.2,652.9,171.9,662.9],"p":170,"i":9,"sec":"essenz-gewoelbe"},{"t":"p","x":"<b>Former:</b> Einmal pro Szene erhältst du, wenn du Kräfte einsetzt, um etwas aus Gold zu formen oder die Stadt zu gestalten, 1 kostenlosen Momentum oder +1 Momentum, wenn du <b>Das Blatt wendest.</b>","sz":9.0,"box":[65.2,667.6,267.0,712.6],"p":170,"i":10,"sec":"essenz-gewoelbe"},{"t":"h","x":"SCHICHT 4:","sz":14.0,"box":[309.0,69.1,377.2,83.1],"p":170,"i":11,"skip":true,"sec":"schicht-4-armands-labor"},{"t":"h","x":"ARMANDS LABOR","sz":23.0,"box":[309.0,91.4,474.2,114.4],"p":170,"i":12,"skip":true},{"t":"h","x":"ARMANDS LABOR","sz":16.0,"box":[334.8,128.0,449.7,144.0],"p":170,"i":13,"skip":true,"sec":"armands-labor"},{"t":"ro","x":"Eine alte Schallplatte spielt im Hintergrund, als ihr die gemütliche Höhle betretet, die als Labor dient. Hinter einer komplizierten Struktur aus Glasbechern, Brennern und spiralförmigen Schläuchen seht ihr das verzerrte Gesicht eines alten, faltigen Mannes. Doch als er hervortritt, steht ein Mann mittleren Alters in einem eleganten Anzug vor euch. „Ich habe Sie erwartet“, sagt er, während er Pulver in ein Fläschchen schüttet, ohne euch anzusehen, „Sie sind die letzte Zutat.“","sz":9.0,"box":[317.5,146.4,538.9,274.2],"p":170,"i":14,"sec":"armands-labor"},{"t":"p","x":"Tief unter dem Anwesen lebt Armand Kai noch immer und widmet jede seiner wachen Stunden der Suche nach dem ultimativen Mittel gegen den Tod. Hier, in seinem Alchemistenlabor, inmitten von Bechern, Mörsern, Stößeln und rauchenden, blubbernden Flüssigkeiten, forscht er nach der Essenz von Mythen, die ihm die Unsterblichkeit verleihen, nach der er sich verzweifelt sehnt. Dabei übersieht er die Tatsache, dass er sein Material aus den Seelen von Menschen gewinnt. Er braut auch Tinkturen aus verschiedenen Mythen-Essenzen zusammen, die ihm nützlich sein könnten.","sz":9.5,"box":[309.0,283.2,541.2,417.7],"p":170,"i":15,"sec":"armands-labor"},{"t":"p","x":"Die Konfrontation mit Armand erinnert an den Zauberer von Oz: Nachdem das Team alle Hindernisse überwunden hat, stellt es fest, dass Armand – trotz Ambitionen und Macht - ein kleinkarierter, egoistischer und von Angst getriebener Mann ist, bereit, das Leben anderer zu opfern, um sich zu retten. Alles unter dem Deckmantel des esoterischen großen Werks.","sz":9.5,"box":[309.0,426.4,538.8,510.9],"p":170,"i":16,"sec":"armands-labor"},{"t":"p","x":"Armand ist kein Scharlatan. Seine Magie ist sehr real und komplex. Er beschwor alchemistische Konstrukte (wie den Eurynomos) als Unterstützung bei der Verarbeitung der Mythos-Essenzen, von denen das größte <b>Aqua Regia</b> ist, ein Elementar der stärksten Säure, das in der Lage ist, Gold – und Mythen – zu schmelzen. Da er wusste, dass nur Risse nach ihm suchen würden, machte er dieses Elementar nicht nur zu seinem Assistenten, sondern zu seinem Leibwächter.","sz":9.5,"box":[309.0,519.5,539.8,629.0],"p":170,"i":17,"sec":"armands-labor"},{"t":"sh","x":"<b>KONFRONTATION MIT ARMAND KAI</b>","sz":10.0,"box":[309.4,642.6,507.0,652.6],"p":170,"i":18,"sec":"armands-labor"},{"t":"p","x":"Dank Corbin Payne hat Armand ein emotionales Trauma legendären Ausmaßes (die Nimmer heilende Wunde, S. 18). Seine Angst vor dem Tod beherrscht ihn so sehr, dass er, um zu entkommen, alles tun und alle anderen verletzen würde, genau wie Corbin Payne es wollte. Wie alle Gralsritter:innen kann Armand andere mit seinem Schmerz, seiner krankhaften Angst vor dem Tod, anstecken. Diese Angst sickerte in seinen falschen Kult (<i>Der Kult des Gottkönigs</i>, S. 113) und die,","sz":9.5,"box":[309.0,658.2,539.8,767.7],"p":170,"i":19,"sec":"armands-labor"}],"size":[595.276,841.89]},"171":{"tab":"","blocks":[{"t":"p","x":"die mit ihm gearbeitet haben (Rachel Woods in <i>Athanor</i>, S. 87). Nun sieht sich das Team mit der vollen Wucht der gierigen Seele konfrontiert – und mit der eigenen Gier und Verlangen nach Besitz, Hab und Gut.","sz":9.5,"box":[53.9,62.5,282.4,109.5],"p":171,"i":0,"sec":"armands-labor"},{"t":"p","x":"Wenn das Team Armand angreift, zieht er sich in die <b>Gralswasserhöhle</b> zurück, einen Nebenraum, in dem die Gralswasserphiole über einem steinernen Altar schwebt, umgeben von einem seichten Graben. Dieser ist mit der Flüssigkeit des Aqua Regia (das sich als Mensch materialisieren kann) gefüllt: Risse und Mythos-Kräfte können den Graben nicht queren, ohne in die Mythen schmelzende Säure zu geraten.","sz":9.5,"box":[53.9,118.2,281.0,215.2],"p":171,"i":1,"sec":"armands-labor"},{"t":"p","x":"<b>Wie in einem Film ist Armand gerade dabei, das Elixier des Lebens zu vervollständigen, als das Team eintrifft.</b> Sein <i>Gebräu</i>-Spektrum repräsentiert den alchemistischen Prozess. Wenn es voll ist, ist das Elixier fertig, und er braucht nur eine einzige harte Aktion, um es zu trinken. Armand nun in der Lage, das Elixier herzustellen, weil:","sz":9.5,"box":[53.9,223.9,283.1,308.3],"p":171,"i":2,"sec":"armands-labor"},{"t":"p","x":"• <b>Es auf einer Mythos-Essenz basiert, die er in einem der vorherigen Fälle erhalten hat</b>, z. B. Juan Delamars Essenz der Ningyo, der japanischen Meerjungfrau, deren Fleisch ewiges Leben verleiht (<i>Athanor</i>) oder Mondgeists/Tracy Changs Mythos-Essenz von Chang’e, der unsterblichen chinesischen Mondgöttin (<i>Der Kult des Gottkönigs</i>) oder","sz":9.5,"box":[53.9,319.8,286.2,404.3],"p":171,"i":3,"sec":"armands-labor"},{"t":"p","x":"• <b>Er als letzte Zutat die Essenz eines der SC oder eines verbündeten Risses verwendet.</b> Dann wird Armand Aqua Regia den Riss attackieren lassen, um die Tinktur zu holen und das Elixier zu beenden.","sz":9.5,"box":[53.9,413.0,280.4,460.0],"p":171,"i":4,"sec":"armands-labor"},{"t":"sh","x":"<b>TRÄNKE TRINKEN</b>","sz":10.0,"box":[54.3,483.3,153.9,493.3],"p":171,"i":5,"sec":"armands-labor"},{"t":"p","x":"Wenn das Team Armand daran hindert, das Elixier zu erschaffen, kann es das <b>Gralswasser</b> erhalten, eine mächtige und unberechenbare Substanz, die kosmische Magie oder ein edles Opfer erfordert, um aktiv zu werden. Wenn man seine Macht anzapft, während ein SC <b>Jetzt reicht’s!</b> nutzt, ist das nötige Opfer 1 Stufe niedriger als die, die die SL nennt (z. B. ein ultimativer Effekt durch ein unumkehrbares Opfer oder ein bedeutender ohne). Das verbraucht das Gralswasser.","sz":9.5,"box":[53.9,498.8,284.9,608.3],"p":171,"i":6,"sec":"armands-labor"},{"t":"p","x":"Wenn Armand das <b>Lebenselixier</b> komplettiert, bezieht es seine Kraft aus dem Gralswasser, das dann verbraucht oder verunreinigt wird. Das Elixier verleiht einem SC oder NSC Immunität gegen den Tod und stellt Jugend und Gesundheit wieder her, wenn er krank oder alt ist oder im Sterben liegt. Dies könnte das Heilmittel für Corbin Payne sein, wenn du diese Ebene als letzte der Kampagne spielst (s. S. Textkasten). Beachte, dass Armand und sein Mythos die Quelle der Magie sind, die das Elixier herstellt. Wenn man ihn tötet oder des Mythos beraubt, kann es unmöglich werden, das Elixier zu vervollständigen, oder die Wirkung kehrt sich um.","sz":9.5,"box":[53.9,617.0,286.3,764.0],"p":171,"i":7,"sec":"armands-labor"},{"t":"h","x":"ERLEUCHTUNG ODER NEKROMANTIE?","sz":14.0,"box":[320.3,61.0,494.3,75.0],"p":171,"i":8,"sec":"armands-labor"},{"t":"p","x":"Wenn du die Kampagne leitest, sollten die Aktionen der SC die Art von Armands Elixier bestimmen.","sz":9.0,"box":[320.3,87.5,524.2,108.5],"p":171,"i":9,"sec":"armands-labor"},{"t":"p","x":"Das Elixier ist nicht wie erhofft. Als vom Schmerz verzehrter Gralsritter kann Armand seine Kräfte nicht einsetzen, um etwas wirklich Gutes zu erzeugen, sondern nur eine weitere, lebensverlängernde Lösung schaffen, die ihn immer wieder in den ewigen Teufelskreis versetzt, ähnlich wie ein Nekromant.","sz":9.0,"box":[320.3,117.2,530.0,186.2],"p":171,"i":10,"sec":"armands-labor"},{"t":"p","x":"Im Gegensatz zu Armands Schmerz versinnbildlicht der Tropfen Gralswasser das Potenzial, wirklich zu heilen und die vierte Stufe des Magnum Opus zu erreichen. Allerdings muss ein wahrhaft <t>geheilter</t> SC die Kraft aktivieren, sonst bleibt sie inaktiv (s. S. Heilung des geheimen Schmerzes, S. 262). Wenn die SC Armand von der Nimmer heilende Wunde heilen oder eine selbstlose Tat vollbringen, könnte er sie auf den geheimen Schmerz hinweisen. Nur dann kann das Elixier zum Trank des ewigen Lebens werden.","sz":9.0,"box":[320.3,194.8,530.1,311.8],"p":171,"i":11,"sec":"armands-labor"},{"t":"p","x":"<b>Wenn man ihn mit seinen Taten konfrontiert, wird Armand von der Begegnung mit Corbin Payne berichten, die ihn auf diesen Weg geführt hat.</b> Psychometrie, Retrokognition oder die Durchsicht seiner wirren Memoiren könnten ähnliche Details zutage fördern.","sz":10.0,"box":[317.5,351.7,531.9,424.2],"p":171,"i":12,"sec":"armands-labor"},{"t":"card","x":"Obwohl das Gralswasser und das theoretische Wissen, das für den Stein der Weisen erforderlich ist, seit vielen Jahren in seinen Händen sind, <b>konnte Armand das Große Werk nie vollenden, weil er sich nie von dem Schmerz lösen konnte (er hat nicht mal die Schwärzung vollendet)</b>. Die Nimmer heilende Wunde hat die lähmende Angst verewigt und ihn zu einem sehr, sehr langen Leben im Elend verurteilt.","sz":null,"k":"yellow","box":[309.3,439.2,541.7,572.8],"p":171,"i":13,"sec":"armands-labor"},{"t":"card","x":"<b>Im Grunde seines Herzens ist Armand kein kompletter Egoist.</b> Er hat eine Leidenschaft für die Suche nach Wahrheit, die Egoismus überstrahlt, aber sein Überlebensinstinkt, den die Nimmer heilende Wunde anfacht, überschattet alles. Suche und Lebenswille, sind noch in ihm.","sz":null,"k":"yellow","box":[309.3,582.0,541.7,678.5],"p":171,"i":14,"sec":"armands-labor"},{"t":"p","x":"Wenn du <i>Parzival</i> einsetzt, wird Armand Informationen preisgeben, die mit seiner Rolle als Gralsritter zusammenhängen.","sz":10.0,"box":[317.5,693.2,531.0,728.2],"p":171,"i":15,"sec":"armands-labor"}],"size":[595.276,841.89]},"172":{"tab":"","blocks":[{"t":"sh","x":"<b>MYSTISCHE HINWEISE</b>","sz":10.0,"box":[54.3,62.8,178.5,72.8],"p":172,"i":0,"sec":"armands-labor"},{"t":"card","x":"Nach Armands theoretischem Wissen ist die <b>Avatarschaft das Narrengold</b>, eine letztlich vergängliche Macht ohne echte Verwandlung. Jeder Avatar bleibt mit der Stadt verbunden und trägt einen gewissen tödlichen Schmerz in sich, ob er es zugibt oder nicht.","sz":null,"k":"yellow","box":[54.1,81.2,286.6,165.0],"p":172,"i":1,"sec":"armands-labor"},{"t":"p","x":"<b>Nach Armands Wissen gibt es einen Zustand der Vollkommenheit, in dem Mythos und Nebel eins sind.</b> Der Riss transzendiert seinen Seinszustand und wird zu etwas Jenseitigem, Ewigem. Dies ist die wahre vierte Stufe des Magnum Opus, der Vereinigung mit „der Quelle allen Lebens“ und des ewigen Lebens.","sz":10.0,"box":[317.5,80.3,531.5,165.3],"p":172,"i":2,"sec":"armands-labor"},{"t":"threat","stars":"★★★★","name":"ARMAND KAI","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 1 ODER – / HEILEN – / BRAUEN 5","items":["<b>Superhirn</b>: Wenn Armand Kai die Szene betritt, gib ihm <t>intelligent 3</t>.","<b>Leibwächter:innen</b>: Wenn Armand einen Zustand annimmt, vor dem Leibwächter:innen schützen können, nehmen sie diesen stattdessen.","<b>Alchemistischer Schutz</b>: Wenn Armand durch ein Material, eine Substanz oder durch Feuer einen Zustand erleidet, reduziert sich dessen Stufe um 5.","<b>Wimmernder Narr</b>: Als weiche Aktion kann Armand einer Person Todesangst einflößen und sie dadurch <t>ängstlich 2</t> machen.","<b>Meister-Alchemist</b>: Dreimal pro Szene kann er als Einmischung eine harte Transmutation ausführen.","<b>Versprechen des ewigen Lebens</b>: Als Einmischung kann er jemanden überzeugen, dass er die Macht hat, ihn oder Angehörige vor dem Tod zu retten. Das Ziel kann einen Furcht-Zustand durch <t>loyal zu Armand</t> der gleichen Stufe ersetzen."],"box":[128.0,209.8,168.8,221.8],"desc":"Obwohl er über 100 Jahre alt ist, ist Armand kein stereotyper gebrechlicher Alchemist. Stattdessen scheint er ein tatkräftiger Mann mittleren Alters zu sein, gekleidet in einen feinen, aber veralteten Anzug in grellen Farben, mit langem dunklem Haar und Spitzbart. Sein Auftreten ist kalt und gleichgültig, wie jemand, der ein einziges Ziel vor Augen hat.<br><br>Als Alchemist liegen Armands Mythos-Kräfte in seinen Konstrukten (Beschwörungen) wie Aqua Regia und einer breiten Palette von Tinkturen. Er kann Transmutationen einsetzen, um sich zu verteidigen.","p":172,"i":3,"sec":"armands-labor"},{"t":"p","x":"<b>Maximaler Bedrohungswert</b>: Zusammen mit Aqua Regia ist Armand ein ernst zu nehmender Gegner, der in der Lage ist, alle Mythos-Kräfte des Teams zu stehlen, es zu verängstigen und mit seinen Kräften zu dezimieren. <b>Aqua Regia kann man nur mit Logos besiegen</b>, also müssen Risse vorbereitet sein und die Aqua Fortis in der Zisterne meiden, um zu überleben. Überleg dir, ob du deine Spieler:innen vor dieser Herausforderung warnen oder den Schwierigkeitsgrad von Armand und Aqua Regia herabsetzen möchtest. Wenn du den Fall als Raub anlegst, kann das Team Rückblenden nutzen, um sich vorzubereiten.","sz":9.0,"box":[61.8,376.9,276.9,517.9],"p":172,"i":4,"sec":"armands-labor"},{"t":"p","x":"<b>Armand Kais Heilung</b>: Wie alle gescheiterten Gralsritter:innen leidet Armand unter einem tiefen emotionalen Trauma, das ihm der Fischerkönig zugefügt hat, die <b>Nimmer heilende Wunde</b>, einen Zustand der Stufe 6. Nur <b>Jetzt reicht’s!</b> kann diesen Zustand beeinflussen: Um Armand für eine Szene von den Auswirkungen zu befreien, ist ein unumkehrbares Opfer erforderlich, während ihre vollständige Heilung das ultimative Opfer erfordert. Optional kannst du eine <i>Mega!</i> <b>Das Blatt wenden</b>-Aktion die Stufe des Zustands für die Dauer einer Szene verringern.","sz":9.0,"box":[61.8,526.9,276.6,655.9],"p":172,"i":5,"sec":"armands-labor"},{"t":"p","x":"Letztlich sollte die Lösung für das Problem erzählerisch sein. Wenn du die Kampagne spielst, sollte er auf Corbin Payne verweisen – wenn er diese Wunde verursacht hat, kann er sie vielleicht heilen. Wenn man Payne heilt, wird vielleicht auch Armand geheilt usw. Wenn das Team Armand nicht heilen oder besiegen kann, sollte es ihn vielleicht im Labor lassen.","sz":9.0,"box":[61.8,664.9,275.6,745.9],"p":172,"i":6,"sec":"armands-labor"},{"t":"p","x":"• Eine Zutat in den blubbernden Zaubertrank werfen (<t>blubbern 4</t> bei <i>Brauen</i>) • Jemandem den Tod so anschaulich beschreiben, dass er <t>gelähmt durch Todesangst 5</t> bekommt • Eine alchemistische Transmutation aktivieren, geschickter als bei seinen Schüler:innen (wähle eine harte Transmutation aus der Liste unter <b>Jünger:innen Armands</b>, S. 157, und erhöhe den Effekt um 1) • Eine Tinktur auf den Boden werfen und ihren Mythos beschwören (Erschaffe eine neue Bedrohung) • Erde transmutieren, um einen Weg für die Jünger:innen zu schaffen, zu Hilfe zu kommen (Erschaffe eine Bedrohung: <b>Jünger:innen Armands</b>)","sz":9.0,"box":[316.9,463.6,531.3,628.8],"p":172,"i":7,"sec":"armands-labor"},{"t":"p","x":"• In seinem Labor oder seinen Taschen nach einer Zutat suchen • Gierig lachen, wenn Aqua Regia einen Mythos auflöst • Jemanden mit den Worten „Ich kann dich retten!“ um Hilfe bitten","sz":9.0,"box":[316.9,637.6,526.9,706.6],"p":172,"i":8,"sec":"armands-labor"}],"size":[595.276,841.89]},"173":{"tab":"","blocks":[],"size":[595.276,841.89]},"174":{"tab":"","blocks":[{"t":"threat","stars":"★★★★","name":"AQUA REGIA","spectra":"","items":[],"box":[124.3,123.5,165.1,135.5],"p":174,"i":0,"sec":"armands-labor"},{"t":"p","x":"Wenn es materialisiert ist, erscheint das Elementar als Frau aus roter Flüssigkeit. Als Beschwörung führt es Befehle ohne Rückfragen aus und verschwindet in einer Dunstwolke, wenn Armand stirbt oder es verbannt.","sz":9.0,"box":[62.4,146.6,272.4,203.6],"p":174,"i":1,"sec":"armands-labor"},{"t":"p","x":"Wenn Armand ins Aqua Regia fällt, wird es zur Tinktur des Meisteralchemisten Fulcanelli (sein Mythos) und Armand zu einem Schläfer. Die Essenz der Nimmer heilenden Wunde (legendärer Effekt, aber kein Mythos) wird als Nebenprodukt freigesetzt und kann nach Belieben versickern oder jemanden infizieren.","sz":9.0,"box":[62.4,212.6,272.8,281.6],"p":174,"i":2,"sec":"armands-labor"},{"t":"p","x":"<b>Wiedererlangung des eigenen Mythos</b>: Solange er nicht vollständig aufgelöst ist, kann man den Mythos eines Risses aus dem Aqua Regia zurückgewinnen, indem man es bannt. Sobald das Aqua Regia eine Tinktur bildet, ist der Prozess schwieriger umzukehren (s. S. Tinkturen, S. 86). Ein Riss kann Kräfte bewahren, indem er die Tinktur seines eigenen Mythos trägt.","sz":9.0,"box":[62.4,290.6,277.1,371.6],"p":174,"i":3,"sec":"armands-labor"},{"t":"p","x":"der Aktivierung alle (oder 2, um den Schwierigkeitsgrad zu verringern) Stärken, die bei der Aktion zum Einsatz kamen. Eine Bedrohung verliert ihre Bedrohungsaktion. • <b>Königswasser</b>: Von Aqua Regia verbrannte Stärken lassen sich nicht wiederherstellen, solange es existiert, auch nicht durch die Wiederherstellung durch einen Avatar. Avatare können sie mit einer <b>Drehpause</b>-Aktion wiederherstellen. • <b>Legende in der Flasche</b>: Wenn Aqua Regia alle Mythos-Stärken eines SC verbrannt hat, wird er zum Schläfer, und es stellt die Tinktur des Mythos her.","sz":9.0,"box":[317.5,125.4,531.5,278.4],"p":174,"i":4,"sec":"armands-labor"},{"t":"p","x":"• Kondensieren nach dem Vaporisieren (entfernt alle <i>Vaporisiert</i>-Stufen) • Jemanden bespritzen und seinen Mythos auflösen (3 Mythos-Stärken verbrennen) oder <t>chemische Verbrennungen 4</t> verursachen • Behälter oder Objekt korrodieren (<t>korrodiert 3</t> oder Entfernen von 3 Stufen des Zustands Kontrolliert. Passe die Stufe auf Grundlage des korrodierten Materials an)","sz":9.0,"box":[317.5,287.4,529.6,392.4],"p":174,"i":5,"sec":"armands-labor"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN – / NEUT- RALISIEREN – / KONTROLLIEREN 6 / VAPORISIEREN 5 / VERBANNEN 3</b>","sz":12.0,"box":[62.4,382.2,274.5,418.2],"p":174,"i":6,"sec":"armands-labor"},{"t":"p","x":"• <b>Mythos-Lösungsmittel</b>: Aqua Regia löst jede Mythos-Kraft auf, die jemand in der Nähe aktiviert, solange es nicht kontrolliert wird. Verbrenne vor","sz":9.0,"box":[62.4,422.6,275.4,455.6],"p":174,"i":7,"sec":"armands-labor"},{"t":"p","x":"• Opfer umfließen, benetzen und auf sie schwappen, während es alles ringsum qualmend verätzt","sz":9.0,"box":[317.5,401.4,528.8,422.4],"p":174,"i":8,"sec":"armands-labor"}],"size":[595.276,841.89]},"175":{"tab":"","blocks":[{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[40.0,57.9,161.0,83.5],"p":175,"i":0,"sec":"armands-labor"},{"t":"p","x":"Im Folgenden findest du einige Fragen, die du dir stellen solltest, und Punkte, die es beim Abschluss dieses Falles noch zu bedenken gilt:","sz":9.5,"box":[53.9,94.9,282.3,129.4],"p":175,"i":1,"sec":"armands-labor"},{"t":"p","x":"• Wie ist das Team aus Armands Chemiebaukasten entkommen? Wessen Schwächen hat der Eurynomos aufgedeckt, wer hat eine Identität an das Aqua Fortis verloren, ist im Gewölbe mit einem Mythos verschmolzen und wessen Mythos hat das Aqua Regia aufgelöst?","sz":9.5,"box":[53.9,140.9,284.7,212.9],"p":175,"i":2,"sec":"armands-labor"},{"t":"p","x":"• Hat das Team das Ziel erreicht, für das es sich nach Canseliet Manor gewagt hat? Hat es die Beute oder die spezielle Essenz gefunden, die es suchte? Hat es das Lebenselixier erhalten und alle geheilt, die der Heilung bedurften? Was hat es verloren? Wenn jemand das Team geschickt hat, z. B. Ariadne, wie hat diese Person auf den Ausgang reagiert? Hat das Team Lohn erhalten?","sz":9.5,"box":[53.9,221.5,278.0,318.5],"p":175,"i":3,"sec":"armands-labor"},{"t":"p","x":"• Was wurde aus Armand? Konnte er das Lebenselixier vollenden und ewiges Leben erlangen? Hat er das Große Werk vollendet, oder war es eine Interimslösung? Hat das Team ihn gefasst, geheilt, getötet oder entmachtet?","sz":9.5,"box":[53.9,327.2,285.0,386.7],"p":175,"i":4,"sec":"armands-labor"},{"t":"p","x":"• Was wird aus Canseliet Manor? Hat das Team den Betrieb der Mythos-Ernte und -Raffinierung unterbunden? Wenn ja, was hat es mit den Tinkturen gemacht? Ist das Herrenhaus nun eine Attraktion für Schatzsucher? Wer könnte sich dort niederlassen?","sz":9.5,"box":[53.9,395.4,284.7,454.9],"p":175,"i":5,"sec":"armands-labor"},{"t":"p","x":"• Was ist mit Armands Diener:innen und Schöpfungen? Wenn er noch lebt und seine Kräfte hat, haben sie dann noch die ihren? Was werden die Jünger:innen tun, jetzt, da ihre Hoffnungen auf ewiges Leben zunichte gemacht sind? Was ist mit Konstrukten wie dem Eurynomos, den Goldenen und Aqua Regia, die nun ohne Meister dastehen?","sz":9.5,"box":[53.9,463.5,283.1,548.0],"p":175,"i":6,"sec":"armands-labor"},{"t":"p","x":"• Was geschah mit Pelican, dem Schmuggler? Konnte er mit Beute entkommen? Ist er erwacht, und wenn ja, welchen Weg wird er als Riss einschlagen? Wenn er geerntet wurde, ist er dann ohne Seele immer noch ein Schmuggler?","sz":9.5,"box":[53.9,556.7,279.0,616.2],"p":175,"i":7,"sec":"armands-labor"}],"size":[595.276,841.89]}},"figures":[{"id":"eisberg","page":154,"kind":"eisberg","title":"Der Eisberg","file":"img/case06/eisberg.webp","box":[0,372,595,800],"after":null},{"id":"titelbild","page":151,"kind":"art","title":"Titelbild: Der Alchemist","file":"img/case06/titelbild.webp","box":[0,0,595,820],"after":null},{"id":"herrenhaus-plan","page":158,"kind":"plan","title":"Plan: Das Herrenhaus und die Ebenen von Canseliet Manor","file":"img/case06/herrenhaus-plan.webp","box":[3,35,589,782],"after":null},{"id":"zisterne-art","page":164,"kind":"art","title":"Illustration: Die Aqua-Fortis-Zisterne","file":"img/case06/zisterne-art.webp","box":[0,0,595,345],"after":null},{"id":"pelican-karte","page":162,"kind":"art","title":"Themenkarte: Pelican","file":"img/case06/pelican-karte.webp","box":[308,436,544,754],"after":null},{"id":"el-dorado-karte","page":170,"kind":"art","title":"Themenkarte: Die Essenz El Dorados","file":"img/case06/el-dorado-karte.webp","box":[48,425,290,739],"after":null},{"id":"besitzurkunde","page":173,"kind":"handout","title":"Porträts und Besitzurkunde von Canseliet Manor","file":"img/case06/besitzurkunde.webp","box":[0,0,595,828],"after":null},{"id":"aqua-regia-art","page":174,"kind":"art","title":"Illustration: Aqua Regia","file":"img/case06/aqua-regia-art.webp","box":[0,483,595,795],"after":null}],"eisberg":{"page":154,"fig":"eisberg","nodes":[{"label":"Ariadne","layer":0,"x":21.7,"y":49.5,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Armands Einladung","layer":0,"x":36.1,"y":49.5,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Schatzjagd","layer":0,"x":48.9,"y":49.9,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Der Kult des Magnum Opus","layer":0,"x":61.9,"y":49.6,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Ichor-Lieferung","layer":0,"x":74.7,"y":49.1,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Foyer","layer":1,"x":28.7,"y":58.9,"w":11,"h":9.5,"target":"schicht-1-das-herrenhaus"},{"label":"Das verlassene Haus","layer":1,"x":42.6,"y":58.9,"w":11,"h":9.5,"target":"das-verlassene-haus"},{"label":"Quartiere der Jünger:innen","layer":1,"x":56.3,"y":59.3,"w":11,"h":9.5,"target":"quartier-der-juenger-innen"},{"label":"Ichor-Destillerie","layer":1,"x":71.9,"y":58.9,"w":11,"h":9.5,"target":"ichor-destillerie"},{"label":"Aqua-Fortis-Zisterne","layer":2,"x":49.8,"y":67.6,"w":11,"h":9.5,"target":"aqua-fortis-zisterne"},{"label":"Goldmine","layer":3,"x":43.3,"y":74.2,"w":11,"h":9.5,"target":"schicht-3-narrengold"},{"label":"Essenz-Gewölbe","layer":3,"x":57.8,"y":74.2,"w":11,"h":9.5,"target":"essenz-gewoelbe"},{"label":"Armands Labor","layer":4,"x":48.9,"y":81.7,"w":11,"h":9.5,"target":"armands-labor"}]}};
